import React from 'react';
import { View, StyleSheet } from 'react-native';
import { Chip, useTheme } from 'react-native-paper';
import { MaterialCommunityIcons } from '@expo/vector-icons';

const RiskBadge = ({ level, label, size = 'medium', style }) => {
  const theme = useTheme();

  const getRiskConfig = () => {
    const configs = {
      critical: {
        color: theme.medicalAlert.critical.badge,
        backgroundColor: theme.medicalAlert.critical.background,
        textColor: theme.medicalAlert.critical.text,
        icon: 'alert-circle',
        label: label || 'Kritis',
      },
      high: {
        color: theme.medicalAlert.high.badge,
        backgroundColor: theme.medicalAlert.high.background,
        textColor: theme.medicalAlert.high.text,
        icon: 'alert',
        label: label || 'Tinggi',
      },
      medium: {
        color: theme.medicalAlert.medium.badge,
        backgroundColor: theme.medicalAlert.medium.background,
        textColor: theme.medicalAlert.medium.text,
        icon: 'alert-circle-outline',
        label: label || 'Sedang',
      },
      low: {
        color: theme.medicalAlert.low.badge,
        backgroundColor: theme.medicalAlert.low.background,
        textColor: theme.medicalAlert.low.text,
        icon: 'check-circle',
        label: label || 'Rendah',
      },
      healthy: {
        color: theme.colors.success,
        backgroundColor: theme.colors.successContainer,
        textColor: theme.semantic.success.dark,
        icon: 'check-circle',
        label: label || 'Sehat',
      },
    };

    return configs[level] || configs.low;
  };

  const config = getRiskConfig();

  return (
    <Chip
      icon={() => (
        <MaterialCommunityIcons
          name={config.icon}
          size={size === 'small' ? 14 : 16}
          color={config.textColor}
        />
      )}
      textStyle={[
        styles.chipText,
        { color: config.textColor },
        size === 'small' && styles.smallText,
      ]}
      style={[
        styles.chip,
        { backgroundColor: config.backgroundColor },
        size === 'small' && styles.smallChip,
        style,
      ]}
    >
      {config.label}
    </Chip>
  );
};

const styles = StyleSheet.create({
  chip: {
    alignSelf: 'flex-start',
  },
  smallChip: {
    height: 24,
  },
  chipText: {
    fontSize: 12,
    fontWeight: '600',
  },
  smallText: {
    fontSize: 10,
  },
});

export default RiskBadge;

import React from 'react';
import { View, StyleSheet, Animated } from 'react-native';
import { useTheme } from 'react-native-paper';

const SkeletonLoader = ({ width = '100%', height = 60, borderRadius = 8, style }) => {
  const theme = useTheme();
  const animatedValue = React.useRef(new Animated.Value(0)).current;

  React.useEffect(() => {
    const animation = Animated.loop(
      Animated.sequence([
        Animated.timing(animatedValue, {
          toValue: 1,
          duration: 1000,
          useNativeDriver: true,
        }),
        Animated.timing(animatedValue, {
          toValue: 0,
          duration: 1000,
          useNativeDriver: true,
        }),
      ])
    );
    animation.start();

    return () => animation.stop();
  }, [animatedValue]);

  const opacity = animatedValue.interpolate({
    inputRange: [0, 1],
    outputRange: [0.3, 0.7],
  });

  return (
    <Animated.View
      style={[
        styles.skeleton,
        {
          width,
          height,
          borderRadius,
          backgroundColor: theme.colors.surfaceVariant,
          opacity,
        },
        style,
      ]}
    />
  );
};

export const SkeletonCard = ({ style }) => {
  const theme = useTheme();

  return (
    <View
      style={[
        styles.card,
        { backgroundColor: theme.colors.surface },
        theme.shadows.sm,
        style,
      ]}
    >
      <SkeletonLoader width={60} height={60} borderRadius={8} />
      <View style={styles.content}>
        <SkeletonLoader width="70%" height={16} borderRadius={4} />
        <SkeletonLoader width="50%" height={14} borderRadius={4} style={{ marginTop: 8 }} />
        <SkeletonLoader width="40%" height={12} borderRadius={4} style={{ marginTop: 8 }} />
      </View>
    </View>
  );
};

export const SkeletonList = ({ count = 3, style }) => {
  return (
    <View style={style}>
      {Array.from({ length: count }).map((_, index) => (
        <SkeletonCard key={index} style={{ marginBottom: 12 }} />
      ))}
    </View>
  );
};

const styles = StyleSheet.create({
  skeleton: {
    overflow: 'hidden',
  },
  card: {
    flexDirection: 'row',
    padding: 16,
    borderRadius: 12,
  },
  content: {
    flex: 1,
    marginLeft: 12,
    justifyContent: 'center',
  },
});

export default SkeletonLoader;

import React from 'react';
import { View } from 'react-native';
import { Text } from 'react-native-paper';
import { MaterialCommunityIcons } from '@expo/vector-icons';
import { colors as COLORS, withOpacity } from '../../theme/colors';
import { typography as TYPOGRAPHY } from '../../theme/dimensions';

/**
 * StatPill Shared Component
 * @param {string} icon - MaterialCommunityIcons name
 * @param {string} label - Label text
 * @param {string} value - Main value text
 * @param {'vertical' | 'horizontal'} variant - Layout variant
 * @param {object} containerStyle - Optional style overrides
 */
const StatPill = ({ icon, label, value, variant = 'vertical', containerStyle }) => {
  const isVertical = variant === 'vertical';

  return (
    <View
      style={[
        {
          borderRadius: 16,
          backgroundColor: isVertical ? withOpacity(COLORS.textPrimary, 0.3) : withOpacity(COLORS.white, 0.15),
          padding: isVertical ? 12 : 10,
          alignItems: 'center',
          flexDirection: isVertical ? 'column' : 'row',
          flex: isVertical ? 1 : undefined,
          marginHorizontal: isVertical ? 6 : 0,
          marginRight: isVertical ? 0 : 12,
        },
        containerStyle,
      ]}
    >
      <MaterialCommunityIcons name={icon} size={isVertical ? 20 : 18} color={COLORS.white} />
      <View style={{
        marginLeft: isVertical ? 0 : 8,
        alignItems: isVertical ? 'center' : 'flex-start',
        marginTop: isVertical ? 4 : 0,
      }}>
        <Text style={{ color: withOpacity(COLORS.white, 0.7), ...TYPOGRAPHY.overline }}>
          {label}
        </Text>
        <Text style={{ color: COLORS.white, ...TYPOGRAPHY.h5, fontWeight: '700', marginTop: 2 }}>
          {value}
        </Text>
      </View>
    </View>
  );
};

export default StatPill;

import React, { useEffect, useState } from 'react';
import { View, TouchableOpacity } from 'react-native';
import { Text, Button } from 'react-native-paper';
import { MaterialCommunityIcons } from '@expo/vector-icons';
import { colors as THEME_COLORS, withOpacity } from '../../theme/colors';
import { typography as TYPOGRAPHY } from '../../theme/dimensions';

const COLORS = THEME_COLORS;

const iconForStatus = (status) => {
  if (status === 'passed') return ['check-circle', COLORS.success];
  if (status === 'warning') return ['alert-circle', COLORS.warning];
  if (status === 'failed') return ['close-circle', COLORS.error];
  return ['minus-circle-outline', COLORS.textMuted];
};

export default function PreCallSystemCheckSheet({
  visible,
  checks = [],
  canJoin = false,
  audioOnly = false,
  joining = false,
  labels = {},
  onClose,
  onJoin,
}) {
  const [consentAccepted, setConsentAccepted] = useState(false);

  useEffect(() => {
    if (!visible) setConsentAccepted(false);
  }, [visible]);

  if (!visible) return null;

  const effectiveCanJoin = canJoin && consentAccepted;

  return (
    <View style={{ position: 'absolute', top: 0, right: 0, bottom: 0, left: 0, zIndex: 140, backgroundColor: withOpacity(COLORS.black || '#000', 0.52), justifyContent: 'flex-end' }}>
      <View style={{ backgroundColor: COLORS.white, borderTopLeftRadius: 28, borderTopRightRadius: 28, padding: 20 }}>
        <View style={{ flexDirection: 'row', alignItems: 'center', marginBottom: 16 }}>
          <View style={{ width: 44, height: 44, borderRadius: 18, backgroundColor: withOpacity(COLORS.primary, 0.12), alignItems: 'center', justifyContent: 'center', marginRight: 12 }}>
            <MaterialCommunityIcons name="stethoscope" size={22} color={COLORS.primary} />
          </View>
          <View style={{ flex: 1 }}>
            <Text style={{ ...TYPOGRAPHY.bodyLarge, fontWeight: '900', color: COLORS.textPrimary }}>{labels.title}</Text>
            <Text style={{ ...TYPOGRAPHY.caption, color: COLORS.textSecondary, marginTop: 2 }}>
              {audioOnly ? labels.joinAudioOnly : labels.ready}
            </Text>
          </View>
          <TouchableOpacity onPress={onClose} accessibilityRole="button" accessibilityLabel={labels.close}>
            <MaterialCommunityIcons name="close" size={24} color={COLORS.textMuted} />
          </TouchableOpacity>
        </View>

        {checks.map((check) => {
          const [icon, color] = iconForStatus(check.status);
          return (
            <View key={check.key} style={{ flexDirection: 'row', alignItems: 'center', paddingVertical: 10, borderBottomWidth: 1, borderBottomColor: COLORS.border }}>
              <MaterialCommunityIcons name={icon} size={22} color={color} />
              <View style={{ flex: 1, marginLeft: 10 }}>
                <Text style={{ ...TYPOGRAPHY.bodySmall, color: COLORS.textPrimary, fontWeight: '800' }}>{check.label}</Text>
                <Text style={{ ...TYPOGRAPHY.caption, color: COLORS.textSecondary, marginTop: 2 }}>{check.message}</Text>
              </View>
            </View>
          );
        })}

        <TouchableOpacity
          activeOpacity={0.8}
          onPress={() => setConsentAccepted((current) => !current)}
          accessibilityRole="checkbox"
          accessibilityState={{ checked: consentAccepted }}
          accessibilityLabel={labels.recordingConsent || 'Persetujuan rekaman sesi'}
          style={{
            flexDirection: 'row',
            alignItems: 'flex-start',
            marginTop: 14,
            padding: 12,
            borderRadius: 14,
            backgroundColor: withOpacity(COLORS.primary, 0.06),
            borderWidth: 1,
            borderColor: withOpacity(COLORS.primary, 0.16),
          }}
        >
          <MaterialCommunityIcons
            name={consentAccepted ? 'checkbox-marked-circle' : 'checkbox-blank-circle-outline'}
            size={22}
            color={consentAccepted ? COLORS.primary : COLORS.textMuted}
          />
          <Text style={{ ...TYPOGRAPHY.caption, flex: 1, color: COLORS.textSecondary, marginLeft: 10, lineHeight: 18 }}>
            {labels.recordingConsent || 'Saya memahami sesi ini mungkin direkam untuk keperluan dokumentasi klinis sesuai kebijakan privasi Serene Apps.'}
          </Text>
        </TouchableOpacity>

        <Button
          mode="contained"
          disabled={!effectiveCanJoin || joining}
          loading={joining}
          onPress={onJoin}
          style={{ borderRadius: 14, marginTop: 18 }}
          contentStyle={{ height: 48 }}
          buttonColor={COLORS.primary}
        >
          {audioOnly ? labels.joinAudioOnly : labels.ready}
        </Button>
      </View>
    </View>
  );
}

import React, { createContext, useContext, useState, useEffect, useCallback, useMemo } from 'react';
import { useSelector } from 'react-redux';
import { io } from 'socket.io-client';
import { API_BASE_URL } from '../services/api';
import {
  getNotifications as apiGetNotifications,
  markNotificationAsRead as apiMarkNotificationAsRead,
  markAllNotificationsAsRead as apiMarkAllNotificationsAsRead
} from '../services/notificationService';

const NotificationContext = createContext(null);

export function useNotifications() {
  const context = useContext(NotificationContext);
  if (!context) {
    throw new Error('useNotifications must be used within a NotificationProvider');
  }
  return context;
}

const NOTIFICATION_TYPE_META = {
  appointment: { label: 'Janji Temu', icon: 'calendar-clock', color: '#6366F1' },
  payment: { label: 'Pembayaran', icon: 'wallet', color: '#10B981' },
  ai: { label: 'AI Diagnosis', icon: 'brain', color: '#8B5CF6' },
  shop: { label: 'Toko Gigi', icon: 'cart', color: '#F59E0B' },
  system: { label: 'Sistem', icon: 'bell', color: '#6B7280' }
};

function getMobileNotificationType(type) {
  if (!type) return 'system';
  const t = type.toLowerCase();
  if (t.startsWith('appointment_')) return 'appointment';
  if (t === 'chat_invite') return 'appointment';
  if (t.startsWith('treatment_plan_')) return 'appointment';
  if (t.startsWith('payment_') || t.includes('payment')) return 'payment';
  if (t.startsWith('ai_')) return 'ai';
  if (t.startsWith('shop_')) return 'shop';
  return 'system';
}

function getMobileNotificationCTA(type, data) {
  const apptId = data?.appointmentId || '';
  const planId = data?.treatmentPlanId || '';
  const invoiceId = data?.invoiceId || '';

  switch (type) {
    case 'appointment_confirmed':
    case 'appointment_rescheduled':
    case 'appointment_reminder':
      return {
        label: 'Lihat detail',
        route: {
          name: 'AppointmentTab',
          params: { screen: 'BookingConfirm', params: { appointmentId: apptId } },
        }
      };
    case 'chat_invite':
      return {
        label: 'Mulai Chat',
        route: {
          name: 'PatientTeledentistry',
          params: { appointmentId: apptId }
        }
      };
    case 'treatment_plan_sent':
      return {
        label: 'Tinjau Rencana',
        route: {
          name: 'TreatmentPlan',
          params: { treatmentPlanId: planId, invoiceId }
        }
      };
    case 'treatment_plan_approved':
    case 'treatment_plan_rejected':
      return {
        label: 'Lihat Rencana',
        route: {
          name: 'TreatmentPlan',
          params: { treatmentPlanId: planId }
        }
      };
    default:
      return null;
  }
}

function mapDatabaseNotification(dbNotif) {
  const type = getMobileNotificationType(dbNotif.type);
  const cta = getMobileNotificationCTA(dbNotif.type, dbNotif.data);

  return {
    id: dbNotif.id.toString(),
    type,
    title: dbNotif.title,
    message: dbNotif.message,
    timestamp: dbNotif.created_at,
    read: dbNotif.is_read,
    meta: dbNotif.data || {},
    cta
  };
}

export const NotificationProvider = ({ children }) => {
  const user = useSelector((state) => state?.auth?.user);
  const accessToken = useSelector((state) => state?.auth?.accessToken);

  const [notifications, setNotifications] = useState([]);
  const [loading, setLoading] = useState(false);
  const [socket, setSocket] = useState(null);

  const fetchNotifications = useCallback(async (showLoading = false) => {
    try {
      if (showLoading) setLoading(true);
      const res = await apiGetNotifications({ limit: 100 });
      if (res && res.success && res.data?.notifications) {
        const mapped = res.data.notifications.map(mapDatabaseNotification);
        setNotifications(mapped);
      }
    } catch (err) {
      console.error('[NotificationContext Mobile] Failed to load notifications:', err);
    } finally {
      if (showLoading) setLoading(false);
    }
  }, []);

  // Fetch initial on mount / user change
  useEffect(() => {
    if (user && accessToken) {
      fetchNotifications(true);
    } else {
      setNotifications([]);
    }
  }, [user, accessToken, fetchNotifications]);

  // Connect socket
  useEffect(() => {
    if (!user || !accessToken) {
      if (socket) {
        socket.disconnect();
        setSocket(null);
      }
      return;
    }

    console.log('🔌 Connecting mobile notification socket to:', API_BASE_URL);
    const newSocket = io(API_BASE_URL, {
      auth: { token: accessToken },
      transports: ['websocket', 'polling'],
      reconnection: true,
      reconnectionAttempts: 10,
      reconnectionDelay: 1000
    });

    setSocket(newSocket);

    newSocket.on('connect', () => {
      console.log('🔌 Mobile notification socket connected');
    });

    newSocket.on('disconnect', () => {
      console.log('🔌 Mobile notification socket disconnected');
    });

    newSocket.on('notification:new', (newNotif) => {
      console.log('🔔 Received mobile new realtime notification:', newNotif);

      const mapped = mapDatabaseNotification(newNotif);
      setNotifications((prev) => {
        // Prevent duplicate addition
        if (prev.some((n) => n.id === mapped.id)) return prev;
        return [mapped, ...prev];
      });
    });

    return () => {
      newSocket.disconnect();
    };
  }, [user, accessToken]);

  const markAsRead = useCallback(async (id) => {
    try {
      setNotifications((prev) =>
        prev.map((n) => (n.id === id ? { ...n, read: true } : n))
      );
      await apiMarkNotificationAsRead(id);
    } catch (err) {
      console.error('[NotificationContext Mobile] Failed to mark read:', err);
      fetchNotifications();
    }
  }, [fetchNotifications]);

  const markAllAsRead = useCallback(async () => {
    try {
      setNotifications((prev) => prev.map((n) => ({ ...n, read: true })));
      await apiMarkAllNotificationsAsRead();
    } catch (err) {
      console.error('[NotificationContext Mobile] Failed to mark all read:', err);
      fetchNotifications();
    }
  }, [fetchNotifications]);

  const unreadCount = useMemo(() => {
    return notifications.filter((n) => !n.read).length;
  }, [notifications]);

  const value = {
    notifications,
    unreadCount,
    loading,
    fetchNotifications,
    markAsRead,
    markAllAsRead
  };

  return (
    <NotificationContext.Provider value={value}>
      {children}
    </NotificationContext.Provider>
  );
};

import React from 'react';
import { View, ScrollView, StatusBar, Dimensions, TouchableOpacity, Platform, PixelRatio } from 'react-native';
import { Text } from 'react-native-paper';
