// --- UTILS & CONSTANTS ---
const { width: SCREEN_WIDTH, height: SCREEN_HEIGHT } = Dimensions.get('window');

// Skala untuk responsiveness (Base width iPhone 11/Pro ~375)
const scale = SCREEN_WIDTH / 375;
const normalize = (size) => {
  const newSize = size * scale;
  return Math.round(PixelRatio.roundToNearestPixel(newSize));
};

// Titik referensi tinggi header (Ratio layar)
const HEADER_HEIGHT_EXPANDED = SCREEN_HEIGHT < 700 ? SCREEN_HEIGHT * 0.32 : SCREEN_HEIGHT * 0.28;

// --- DATA ---
const FEATURES = [
  { icon: 'tooth-outline', color: '#6366F1', title: 'Cek Karies', desc: 'Deteksi lubang.' },
  { icon: 'water-outline', color: '#EC4899', title: 'Gusi Sehat', desc: 'Cek radang.' },
  { icon: 'file-document-outline', color: '#8B5CF6', title: 'Laporan', desc: 'Hasil medis.' },
];

