import React from 'react';
import { 
  View, 
  StyleSheet, 
  StatusBar, 
  Dimensions, 
  Platform, 
  PixelRatio 
} from 'react-native';
import { Text, ProgressBar, useTheme } from 'react-native-paper';
import { MaterialCommunityIcons } from '@expo/vector-icons';
import { LinearGradient } from 'expo-linear-gradient';
import { useSafeAreaInsets } from 'react-native-safe-area-context';

import { analyzeImage } from '../../../services/aiDiagnosisService';
import { useDispatch } from 'react-redux';
import { syncAnalysisToBackend } from '../../../store/slices/aiSlice';
import useToast from '../../../hooks/useToast';
import ValidationToast from '../../settings/components/ValidationToast';

// --- UTILS RESPONSIVE ---
const { width: SCREEN_WIDTH } = Dimensions.get('window');
const scale = SCREEN_WIDTH / 375; // Base width iPhone 11/Pro

const normalize = (size) => {
  const newSize = size * scale;
  if (Platform.OS === 'ios') {
    return Math.round(PixelRatio.roundToNearestPixel(newSize));
  } else {
    return Math.round(PixelRatio.roundToNearestPixel(newSize)) - 1;
  }
};
// -------------------------

const AnalysisScreen = ({ route, navigation }) => {
  const theme = useTheme();
  const insets = useSafeAreaInsets();
  const { toast, showToast, hideToast } = useToast();
  const dispatch = useDispatch();
  const params = route && route.params ? route.params : {};
  const images = params.images;
  const sessionId = params.sessionId;

  const [progress, setProgress] = React.useState(0);
  const [status, setStatus] = React.useState('Memproses gambar...');
  const analysisRef = React.useRef(false);

  const isModelUnavailableError = (msg = '') => {
    const lower = String(msg || '').toLowerCase();
    return (
      lower.includes('google-generativeai') ||
      lower.includes('location is not supported') ||
      lower.includes('orchestrator_error')
    );
  };

  React.useEffect(() => {
    if (!images || !sessionId || analysisRef.current) return;
    analysisRef.current = true;
    performAnalysis();
  }, [images, sessionId]);

  const performAnalysis = async () => {
    try {
      // Stage 1: Prepare images
      setProgress(0.2);
      setStatus('Memproses gambar...');
      await new Promise((resolve) => setTimeout(resolve, 800));

      // Stage 2: Upload and detect
      setProgress(0.4);
      setStatus('Mendeteksi area gigi...');
      await new Promise((resolve) => setTimeout(resolve, 800));

      // Stage 3: Call AI API
      setProgress(0.6);
      setStatus('Menganalisis kondisi...');

      const analysisResponse = await analyzeImage({
        sessionId,
        imageUris: images.map((img) => img.uri),
        language: 'id',
      });

      // Stage 4: Process results
      setProgress(0.8);
      setStatus('Menghitung tingkat risiko...');
      await new Promise((resolve) => setTimeout(resolve, 600));

      // Stage 5: Complete
      setProgress(1.0);
      setStatus('Selesai!');

      if (analysisResponse && analysisResponse.success && analysisResponse.data) {
        // Background sync to backend (idempotent by sessionId)
        try {
          const vf = analysisResponse.data.visual_findings || {};
          const analysisPayload = {
            id: analysisResponse.data.message_id || sessionId,
            session_id: sessionId,
            findings: analysisResponse.data.reply || analysisResponse.data.content || '',
            summary: vf.summary || vf.overall_summary || '',
            overall_assessment: vf.overall_assessment || '',
            risk_level: vf.concern_level || vf.risk_level || 'unknown',
            confidence_score: typeof vf.confidence === 'number' ? Math.round(vf.confidence * 100) : vf.confidence_score || null,
            detections: vf.detections || [],
            recommendations: vf.recommendations || [],
            image_url:
              analysisResponse.data.source_image_uri ||
              analysisResponse.data.images?.[0]?.url ||
              images[0]?.uri ||
              null,
            annotated_image_url: vf.annotated_image_base64 ? `data:image/jpeg;base64,${vf.annotated_image_base64}` : null,
            timestamp: new Date().toISOString(),
          };
          dispatch(syncAnalysisToBackend(analysisPayload));
        } catch (syncErr) {
          // non-blocking
          if (__DEV__) console.warn('Sync to backend skipped:', syncErr?.message);
        }
        // Navigate to results with API data
        setTimeout(() => {
          navigation.replace('Result', {
            sessionId,
            analysisData: analysisResponse.data,
            images,
          });
        }, 500);
      } else {
        // Handle API error
        const rawError =
          (analysisResponse &&
            analysisResponse.error &&
            analysisResponse.error.message) ||
          (analysisResponse && analysisResponse.error) ||
          'Terjadi kesalahan saat menganalisis gambar.';

        const errorMessage =
          typeof rawError === 'string' ? rawError : JSON.stringify(rawError);

        const isServerError =
          errorMessage.indexOf('504') !== -1 ||
          errorMessage.indexOf('500') !== -1 ||
          errorMessage.toLowerCase().indexOf('timeout') !== -1 ||
          errorMessage.toLowerCase().indexOf('gateway') !== -1 ||
          errorMessage.indexOf('ECONNABORTED') !== -1 ||
          isModelUnavailableError(errorMessage);

        if (isServerError) {
          showToast(
            'Server AI sedang bermasalah. Tim kami sedang memperbaikinya.',
            'error'
          );
        }

        navigation.replace('ServerUnavailable', {
          origin: 'analysis',
          retryParams: { images, sessionId },
          errorDetail: errorMessage,
        });
      }
    } catch (error) {
      const errorMsg =
        (error && error.message) || (error ? String(error) : 'Unknown error');
      const isServerError =
        errorMsg.indexOf('504') !== -1 ||
        errorMsg.indexOf('500') !== -1 ||
        errorMsg.toLowerCase().indexOf('timeout') !== -1 ||
        errorMsg.indexOf('ECONNABORTED') !== -1 ||
        errorMsg.indexOf('Network Error') !== -1 ||
        isModelUnavailableError(errorMsg);

      if (isServerError) {
        showToast(
          'Server tidak merespons. Kemungkinan server sedang down.',
          'error'
        );
      }

      navigation.replace('ServerUnavailable', {
        origin: 'analysis',
        retryParams: { images, sessionId },
        errorDetail: errorMsg,
      });
    }
  };

  const gradient =
    (theme.gradients && theme.gradients.primary) || [
      theme.colors.primary,
      '#7F1DFF',
    ];

  return (
    <LinearGradient
      colors={gradient}
      style={[
        styles.container,
        { paddingTop: insets.top, paddingBottom: insets.bottom },
      ]}
      start={{ x: 0, y: 0 }}
      end={{ x: 1, y: 1 }}
    >
      <StatusBar barStyle="light-content" backgroundColor="transparent" translucent />
      <View style={styles.content}>
        {/* Ikon gigi yang sedang dianalisis */}
        <View style={styles.iconWrapper}>
          <View style={styles.iconCircle}>
            <MaterialCommunityIcons
              name="tooth-outline"
              size={normalize(52)}
              color="#FFFFFF"
            />
            <View style={styles.iconBadge}>
              <MaterialCommunityIcons
                name="magnify-scan"
                size={normalize(20)}
                color="#4F46E5"
              />
            </View>
          </View>
        </View>

        <Text variant="headlineSmall" style={styles.title}>
          Menganalisis gigi...
        </Text>

        <Text variant="bodyLarge" style={styles.status}>
          {status}
        </Text>

        <ProgressBar progress={progress} color="#FFFFFF" style={styles.progressBar} />

        <Text variant="bodySmall" style={styles.progressText}>
          {Math.round(progress * 100)}%
        </Text>
      </View>

      <ValidationToast
        visible={toast.visible}
        message={toast.message}
        status={toast.status}
        onDismiss={hideToast}
      />
    </LinearGradient>
  );
};

const styles = StyleSheet.create({
  container: {
    flex: 1,
  },
  content: {
    flex: 1,
    justifyContent: 'center',
    alignItems: 'center',
    paddingHorizontal: normalize(32),
