    color: 'rgba(255,255,255,0.9)',
    textAlign: 'center',
    fontSize: normalize(16),
  },
  progressBar: {
    width: '100%',
    height: normalize(8),
    borderRadius: normalize(4),
    backgroundColor: 'rgba(255,255,255,0.3)',
