          <MaterialCommunityIcons name="history" size={16} color={COLORS.primary} />
          <Text style={{ fontSize: 13, fontWeight: '600', color: COLORS.primary, marginLeft: 8, flex: 1 }}>
            Lihat Riwayat Chat
