    Animated.timing(healthFormAnim, {
      toValue: next ? 1 : 0,
      duration: 300,
      useNativeDriver: false,
    }).start();
  };

  const healthFormHasContent = Object.entries(healthForm).some(([key, value]) => (
    key === 'painLevel' ? value != null : Boolean(value?.trim?.())
