        try {
          await savePreSessionHealthForm(appointmentId, {
            symptoms: healthForm.symptoms,
            painLevel: healthForm.painLevel,
            allergies: healthForm.allergies,
            medications: healthForm.medications,
            notes: healthForm.notes,
