              </View>
              <Animated.View style={{ maxHeight: healthFormAnim.interpolate({ inputRange: [0, 1], outputRange: [0, 420] }), overflow: 'hidden' }}>
                <View style={{ paddingTop: 14 }}>
                  <TextInput
