          {slotsLoading ? (
            <View style={{ alignItems: 'center', paddingVertical: 30 }}>
              <ActivityIndicator animating color={COLORS.primary} />
              <Text style={{ marginTop: 8, color: COLORS.textSecondary, ...TYPOGRAPHY.bodySmall }}>Memuat jadwal...</Text>
