const DICEBEAR_BG = '8B5CF6';
const API_BASE = API_BASE_URL.replace(/\/$/, '');

// Utility to normalize Dicebear URLs
const normalizeDicebear = (url, seed) => {
  if (!url) return `https://api.dicebear.com/7.x/avataaars/png?seed=${seed}&backgroundColor=${DICEBEAR_BG}&size=256`;
  if (url.includes('dicebear.com')) {
    return url.replace(/\/svg\?/, '/png?').replace(/&size=\d+/, '&size=256');
  }
  return url;
};

// Resolve avatar URL from backend or use Dicebear fallback
const resolveAvatar = (path, seed = 'dentist') => {
  if (!path || typeof path !== 'string') {
    return `https://api.dicebear.com/7.x/avataaars/png?seed=${seed}&backgroundColor=${DICEBEAR_BG}&size=256`;
  }
  return resolveMediaUrl(path) || `https://api.dicebear.com/7.x/avataaars/png?seed=${seed}&backgroundColor=${DICEBEAR_BG}&size=256`;
};

const pickDoctorAvatar = (source = {}) =>
  source?.avatar_url ||
  source?.avatarUrl ||
  source?.user?.avatar_url ||
  source?.user?.avatarUrl ||
  source?.dentist?.avatar_url ||
  source?.avatar ||
  source?.image ||
  source?.imageUrl ||
  source?.photo ||
  null;

// Format clinic distance
const formatClinicDistance = (distanceKm) => {
  if (typeof distanceKm === 'number') {
    return `${distanceKm.toFixed(1)} km`;
  }
  return '—';
};

const DAY_KEYS = ['monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday', 'sunday'];
const DAY_LABELS = ['Senin', 'Selasa', 'Rabu', 'Kamis', 'Jumat', 'Sabtu', 'Minggu'];

const normalizeHours = (hours) => {
  if (!hours || typeof hours !== 'object') return [];
  return DAY_KEYS.map((key, index) => {
    const value = hours[key] || hours[DAY_LABELS[index]?.toLowerCase?.()] || hours[index];
    const open = value?.open || value?.openTime || value?.start || value?.from;
    const close = value?.close || value?.closeTime || value?.end || value?.to;
    const closed = value?.closed || value === null || value === 'closed' || value === 'Tutup';
    return {
      key,
      label: DAY_LABELS[index],
      value: closed || (!open && !close) ? 'Tutup' : `${open || '—'}–${close || '—'}`,
    };
  });
};

