const ClinicDetailScreen = () => {
  const theme = useTheme();
  const navigation = useNavigation();
  const route = useRoute();
  const insets = useSafeAreaInsets();
  const scrollViewRef = useRef(null);
  const [activeSection, setActiveSection] = useState('kontak');
  const [anchorHeight, setAnchorHeight] = useState(64);
  const initialClinic = route.params?.clinic || null;
  const [clinic, setClinic] = useState(initialClinic);
  const [loading, setLoading] = useState(!initialClinic);
  const [error, setError] = useState(null);
  const [favoriteClinicIds, setFavoriteClinicIds] = useState([]);
  const [hoursExpanded, setHoursExpanded] = useState(false);
  const favoriteScale = useRef(new Animated.Value(1)).current;
  const hoursAnim = useRef(new Animated.Value(0)).current;

  const { toast, showToast, hideToast } = useToast();

  // Store section positions
  const sectionPositions = useRef({
    kontak: 0,
    jam: 0,
    keunggulan: 0,
    layanan: 0,
    dokter: 0,
    fasilitas: 0,
    galeri: 0,
  });

  const { headerHeight, handleHeaderLayout } = useAnchoredHeaderHeight(360);

  const clinicId = route.params?.clinicId || initialClinic?.id;
  const isLiveClinicId = /^\d+$/.test(clinicId?.toString?.() || '');

  useEffect(() => {
    AsyncStorage.getItem('favoriteClinicIds')
      .then((value) => setFavoriteClinicIds(JSON.parse(value || '[]')))
      .catch(() => null);
  }, []);

  useEffect(() => {
    if (!clinic?.id || !clinic?.name) return;
    AsyncStorage.getItem('recentlyViewedClinics')
      .then((value) => {
        const current = JSON.parse(value || '[]');
        const entry = { id: clinic.id?.toString?.() || clinic.id, name: clinic.name };
        const next = [entry, ...current.filter((item) => item.id !== entry.id)].slice(0, 5);
        return AsyncStorage.setItem('recentlyViewedClinics', JSON.stringify(next));
      })
      .catch(() => null);
  }, [clinic?.id, clinic?.name]);

  useEffect(() => {
    let ignore = false;
    const loadClinic = async () => {
      if (!clinicId || !isLiveClinicId) {
        setLoading(false);
        if (!initialClinic && !clinicId) {
          setError('Data klinik tidak tersedia');
        }
        return;
      }

      try {
        setLoading(true);
        console.log('🏥 [ClinicDetail] Loading clinic:', clinicId);
        const response = await fetchClinicById(clinicId);
        console.log('🏥 [ClinicDetail] Raw response:', response);

        // Backend returns { success: true, data: {...} }
        const clinicData = response?.data || response;
        console.log('🏥 [ClinicDetail] Clinic data:', clinicData);

        if (!clinicData) {
          throw new Error('Data klinik tidak ditemukan');
        }

        // Map backend data to component format
        const mappedClinic = {
          id: clinicData.id || clinicData.branchId,
          name: clinicData.name,
          tagline: clinicData.tagline,
          address: clinicData.address,
          city: clinicData.city,
          province: clinicData.province,
          distanceKm: clinicData.distanceKm || route.params?.clinic?.distanceKm,
          rating: clinicData.rating || 0,
          reviews: clinicData.reviews || 0,
          queue: clinicData.queue || 'N/A',
          openStatus: clinicData.openStatus || 'Tutup',
          isOpenNow: clinicData.isOpenNow || false,
          phone: clinicData.phone || clinicData.contact?.phone,
          email: clinicData.email || clinicData.contact?.email,
          contact: {
            phone: clinicData.phone || clinicData.contact?.phone,
            email: clinicData.email || clinicData.contact?.email,
          },
          heroImage: clinicData.heroImage,
          coverImage: clinicData.coverImage,
          gallery: clinicData.gallery || [],
          highlights: clinicData.highlights || [],
          facilities: clinicData.facilities || [],
          services: (clinicData.services || []).map(service => ({
            name: service.name,
            description: service.description,
            price: service.price,
          })),
          doctors: (clinicData.doctors || []).map(doctor => ({
            id: doctor.id || doctor.userId,
            userId: doctor.userId,
            name: doctor.name,
            avatar: resolveAvatar(pickDoctorAvatar(doctor), doctor.id || doctor.userId),
            specialty: doctor.specialty,
            experience: doctor.experience,
            rating: parseFloat(doctor.rating) || 0,
            slots: doctor.slots || [],
          })),
          operatingHours: clinicData.operatingHours,
          dentistCount: clinicData.doctors?.length || 0,
          treatmentRooms: clinicData.treatmentRooms,
          badgeColor: '#EEF2FF',
        };

        console.log('🏥 [ClinicDetail] Mapped clinic:', mappedClinic);
        if (!ignore) {
          setClinic(mappedClinic);
          setError(null);
        }
      } catch (err) {
        console.log('🔍 [ClinicDetail] Failed to load clinic:', err.message);
        if (!ignore) {
          setError('Tidak dapat memuat detail klinik');
          showToast('Gagal memuat data klinik', 'error');
        }
      } finally {
        if (!ignore) {
          setLoading(false);
        }
      }
    };

    loadClinic();
    return () => {
      ignore = true;
    };
  }, [clinicId, isLiveClinicId]);

  const sections = [
    { id: 'kontak', label: 'Kontak', icon: 'map-marker' },
    { id: 'jam', label: 'Jam', icon: 'clock-outline' },
    { id: 'keunggulan', label: 'Keunggulan', icon: 'star' },
    { id: 'layanan', label: 'Layanan', icon: 'medical-bag' },
    { id: 'dokter', label: 'Dokter', icon: 'doctor' },
    { id: 'fasilitas', label: 'Fasilitas', icon: 'hospital-building' },
    { id: 'galeri', label: 'Galeri', icon: 'image-multiple' },
  ];

  const scrollToSection = (sectionId) => {
    const position = sectionPositions.current[sectionId];
    if (scrollViewRef.current && position !== undefined) {
      scrollViewRef.current.scrollTo({
        y: Math.max(position - anchorHeight, 0),
        animated: true,
      });
      setActiveSection(sectionId);
    }
  };

  const handleSectionLayout = (sectionId, event) => {
    const { y } = event.nativeEvent.layout;
    sectionPositions.current[sectionId] = y;
  };

  const handleScroll = (event) => {
    const offsetY = event.nativeEvent.contentOffset.y + anchorHeight + 16;
    let currentSection = sections[0].id;
    for (const section of sections) {
      const position = sectionPositions.current[section.id];
      if (position !== undefined && offsetY >= position) {
        currentSection = section.id;
      } else {
        break;
      }
    }
    if (currentSection !== activeSection) {
      setActiveSection(currentSection);
    }
  };

  // 1. Auto-scroll effect when landing via "Booking" action
  useEffect(() => {
    if (route.params?.autoScrollToBooking && !loading && clinic) {
      // Delay slightly to ensure layout is ready
      const timer = setTimeout(() => {
        scrollToSection('dokter');
        // Clear param to avoid re-scroll on other updates
        navigation.setParams({ autoScrollToBooking: undefined });
      }, 500);
      return () => clearTimeout(timer);
    }
  }, [route.params?.autoScrollToBooking, loading, clinic]);

  const handleBook = () => scrollToSection('dokter');

  const handleCall = () => {
    if (clinic?.phone || clinic?.contact?.phone) {
      Linking.openURL(`tel:${clinic?.phone || clinic?.contact?.phone}`).catch(() => { });
    }
  };

  const toggleFavorite = () => {
    const id = clinic?.id?.toString?.() || clinic?.id;
    if (!id) return;
    const next = favoriteClinicIds.includes(id)
      ? favoriteClinicIds.filter((item) => item !== id)
      : [...favoriteClinicIds, id];
    setFavoriteClinicIds(next);
    AsyncStorage.setItem('favoriteClinicIds', JSON.stringify(next)).catch(() => null);
    favoriteScale.setValue(1);
    Animated.sequence([
      Animated.spring(favoriteScale, { toValue: 1.35, friction: 3, useNativeDriver: true }),
      Animated.spring(favoriteScale, { toValue: 1, friction: 4, useNativeDriver: true }),
    ]).start();
  };

  const toggleHours = () => {
    const next = !hoursExpanded;
    setHoursExpanded(next);
    Animated.timing(hoursAnim, {
      toValue: next ? 1 : 0,
      duration: 250,
      easing: Easing.out(Easing.ease),
      useNativeDriver: false,
    }).start();
  };

  if (loading) {
    return (
      <View style={{ flex: 1, backgroundColor: COLORS.surface, justifyContent: 'center', alignItems: 'center' }}>
        <ActivityIndicator size="large" color={COLORS.primary} />
        <Text style={{ marginTop: 16, color: COLORS.textSecondary, ...TYPOGRAPHY.bodySmall }}>Memuat detail klinik...</Text>
      </View>
    );
  }

  if (error || !clinic) {
    return (
      <View style={{ flex: 1, backgroundColor: COLORS.surface, justifyContent: 'center', alignItems: 'center', padding: 20 }}>
        <MaterialCommunityIcons name="hospital-box-outline" size={64} color={COLORS.textMuted} />
        <Text style={{ marginTop: 16, ...TYPOGRAPHY.h4, color: COLORS.textPrimary }}>
          {error || 'Klinik tidak ditemukan'}
        </Text>
        <Button mode="contained" onPress={() => navigation.goBack()} style={{ marginTop: 16 }}>
          Kembali
        </Button>
      </View>
    );
  }

  return (
    <View style={{ flex: 1, backgroundColor: COLORS.surface }}>
      <StatusBar barStyle="light-content" backgroundColor="transparent" translucent />

      {/* HEADER / HERO */}
      <View
        onLayout={handleHeaderLayout}
        style={{
          position: 'absolute',
          left: 0,
          right: 0,
          top: 0,
          zIndex: 20,
          elevation: 20,
        }}
      >
        <LinearGradient
          colors={COLORS.headerGradient}
          start={{ x: 0, y: 0 }}
          end={{ x: 1, y: 1 }}
          style={{
            paddingTop: insets.top + 2,
            paddingHorizontal: 20,
            paddingBottom: 32,
            borderBottomLeftRadius: 36,
            borderBottomRightRadius: 36,
            overflow: 'hidden',
          }}
        >
          {/* Decorative Background Accent */}
          <View
            style={{
              position: 'absolute',
              left: -40,
              top: -40,
              width: 180,
              height: 180,
              borderRadius: 90,
              backgroundColor: withOpacity(COLORS.white, 0.04),
            }}
          />

          <View style={{ flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center' }}>
