          borderTopWidth: 1,
          borderTopColor: COLORS.border || COLORS.gray200,
          flexDirection: 'row',
          alignItems: 'center',
          justifyContent: 'center',
          paddingBottom: Math.max(insets.bottom, 14),
        }}>
          <MaterialCommunityIcons name="chat-lock-outline" size={20} color={COLORS.textMuted || COLORS.gray500} />
