                >
                  <SafeTwilioVideoParticipantView
                    style={{ flex: 1, backgroundColor: COLORS.black }}
                    trackIdentifier={{
                      participantSid: remoteTrack.participantSid,
                      videoTrackSid: remoteTrack.videoTrackSid
                    }}
                  />
                  <View style={{ position: 'absolute', left: 10, bottom: 10, backgroundColor: withOpacity(COLORS.black, 0.45), borderRadius: 12, paddingHorizontal: 10, paddingVertical: 5 }}>
                    <Text style={{ color: COLORS.white, fontSize: 11, fontWeight: '700' }} numberOfLines={1}>
                      {remoteTrack.identity?.includes('dentist') ? 'Dokter' : safeDentistName}
                    </Text>
                  </View>
                </View>
              ))}
            </View>
          ) : (
            <LinearGradient colors={['#0F172A', '#1E293B']} style={{ flex: 1, justifyContent: 'center', alignItems: 'center' }}>
              <View style={{ position: 'relative' }}>
                {resolvedAvatar ? (
                  <Image source={{ uri: resolvedAvatar }} style={{ width: 100, height: 100, borderRadius: 50, borderWidth: 3, borderColor: withOpacity(COLORS.white, 0.2), marginBottom: 16 }} onError={() => setAvatarError(true)} />
                ) : (
                  <LinearGradient colors={[COLORS.primaryLight, COLORS.primary]} style={{ width: 100, height: 100, borderRadius: 50, justifyContent: 'center', alignItems: 'center', marginBottom: 16 }}>
                    <Text style={{ fontSize: 36, fontWeight: '700', color: COLORS.white }}>{dentistInitials}</Text>
                  </LinearGradient>
                )}
                <Text style={{ fontSize: 20, fontWeight: '700', color: COLORS.white, textAlign: 'center' }}>{safeDentistName}</Text>
                <Text style={{ fontSize: 13, color: withOpacity(COLORS.white, 0.5), marginTop: 4, textAlign: 'center' }}>{displaySpecialty}</Text>
                <Text style={{ fontSize: 14, color: COLORS.accent, marginTop: 12, textAlign: 'center' }}>
                  {remoteParticipants.length > 0 ? 'Audio tersambung. Kamera dokter tidak aktif.' : 'Menunggu terhubung...'}
                </Text>
              </View>
            </LinearGradient>
          )}
        </View>

        {/* Top Bar: Timer + Back */}
        <SafeAreaView style={{ position: 'absolute', top: 0, left: 0, right: 0, zIndex: 10 }}>
          <View style={{ flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between', paddingHorizontal: 16, paddingTop: 8 }}>
            <TouchableOpacity style={{ width: 40, height: 40, borderRadius: 20, backgroundColor: withOpacity(COLORS.white, 0.15), justifyContent: 'center', alignItems: 'center' }} onPress={handleEndCall} accessibilityLabel="Kembali" accessibilityRole="button">
              <MaterialCommunityIcons name="arrow-left" size={22} color={COLORS.white} />
            </TouchableOpacity>
            <View style={{ flexDirection: 'row', alignItems: 'center', backgroundColor: withOpacity(COLORS.white, 0.15), paddingHorizontal: 14, paddingVertical: 6, borderRadius: 20 }}>
              <View style={{ width: 8, height: 8, borderRadius: 4, backgroundColor: callStateColor, marginRight: 8 }} />
              <Text style={{ color: COLORS.white, fontSize: 11, fontWeight: '700', marginRight: 8 }}>{callStateLabel}</Text>
              <Text style={{ color: COLORS.white, fontSize: 14, fontWeight: '700', fontVariant: ['tabular-nums'] }}>{formatCallDuration(callDuration)}</Text>
              <MaterialCommunityIcons name="signal-cellular-2" size={14} color={COLORS.white} style={{ marginLeft: 10, marginRight: 4 }} />
              <Text style={{ color: COLORS.white, fontSize: 12, fontWeight: '700' }}>{networkQuality >= 0 ? networkQuality : '-'}/5</Text>
            </View>
            <TouchableOpacity
              onPress={() => setShowConnectionDiagnostics(true)}
              accessibilityLabel="Diagnostik Koneksi"
              accessibilityRole="button"
              style={{ width: 40, height: 40, borderRadius: 20, backgroundColor: withOpacity(COLORS.white, 0.15), justifyContent: 'center', alignItems: 'center' }}
            >
              <MaterialCommunityIcons name="dots-horizontal" size={22} color={COLORS.white} />
            </TouchableOpacity>
          </View>
        </SafeAreaView>

        {networkQuality >= 0 && networkQuality <= 1 && (
          <View style={{ position: 'absolute', top: insets.top + 58, left: 16, right: 16, zIndex: 11, backgroundColor: withOpacity(COLORS.warning, 0.92), borderRadius: 12, padding: 10 }}>
            <Text style={{ color: COLORS.white, fontSize: 12, fontWeight: '700', textAlign: 'center' }}>
              Kualitas jaringan buruk. Gunakan audio-only bila video terputus.
            </Text>
            {isVideoEnabled && (
              <TouchableOpacity
                onPress={switchToAudioOnly}
                style={{ marginTop: 8, alignSelf: 'center', borderWidth: 1, borderColor: withOpacity(COLORS.white, 0.5), borderRadius: 8, paddingHorizontal: 12, paddingVertical: 6 }}
              >
                <Text style={{ color: COLORS.white, fontSize: 12, fontWeight: '700' }}>Audio only</Text>
              </TouchableOpacity>
            )}
          </View>
        )}

        {callNotice && (
          <View style={{ position: 'absolute', top: insets.top + (networkQuality >= 0 && networkQuality <= 1 ? 142 : 58), left: 16, right: 16, zIndex: 11, backgroundColor: withOpacity(isReconnecting ? COLORS.warning : COLORS.error, 0.92), borderRadius: 12, padding: 10 }}>
            <Text style={{ color: COLORS.white, fontSize: 12, fontWeight: '700', textAlign: 'center' }}>{callNotice}</Text>
          </View>
        )}

        {/* PIP (Patient Camera) */}
        <View style={{ position: 'absolute', right: 16, width: 110, height: 150, borderRadius: 16, overflow: 'hidden', borderWidth: 2, borderColor: withOpacity(COLORS.white, 0.3), elevation: 10, shadowColor: COLORS.black, shadowOffset: { width: 0, height: 4 }, shadowOpacity: 0.4, shadowRadius: 8, top: insets.top + 60, backgroundColor: '#263238' }}>
          {isVideoEnabled ? (
            <SafeTwilioVideoLocalView enabled={true} style={{ flex: 1 }} />
          ) : (
            <LinearGradient colors={['#37474F', '#263238']} style={{ flex: 1, justifyContent: 'center', alignItems: 'center' }}>
              <MaterialCommunityIcons name="camera-off" size={32} color={withOpacity(COLORS.white, 0.6)} />
              <Text style={{ color: withOpacity(COLORS.white, 0.5), fontSize: 10, marginTop: 4 }}>Kamera Mati</Text>
            </LinearGradient>
          )}
        </View>

        {/* Bottom Controls */}
        <View style={{ position: 'absolute', bottom: 0, left: 0, right: 0, paddingTop: 20, paddingBottom: Math.max(insets.bottom, 20) }}>
          <View style={{ flexDirection: 'row', justifyContent: 'center', gap: 16, paddingHorizontal: 20 }}>
            {/* Mute */}
            <TouchableOpacity
              style={{ alignItems: 'center', justifyContent: 'center', width: 64, height: 76, borderRadius: 20, backgroundColor: !isAudioEnabled ? withOpacity(COLORS.white, 0.3) : withOpacity(COLORS.white, 0.15), paddingTop: 6 }}
              onPress={toggleAudio}
              activeOpacity={0.8}
              accessibilityLabel={!isAudioEnabled ? "Nyalakan Mikrofon" : "Matikan Mikrofon"}
              accessibilityRole="button"
            >
              <MaterialCommunityIcons name={!isAudioEnabled ? 'microphone-off' : 'microphone'} size={24} color={COLORS.white} />
              <Text style={{ color: COLORS.white, ...TYPOGRAPHY.caption, fontWeight: '500', marginTop: 4 }}>{!isAudioEnabled ? 'Unmute' : 'Mute'}</Text>
            </TouchableOpacity>

            {/* Camera Toggle */}
            <TouchableOpacity
              style={{ alignItems: 'center', justifyContent: 'center', width: 64, height: 76, borderRadius: 20, backgroundColor: !isVideoEnabled ? withOpacity(COLORS.white, 0.3) : withOpacity(COLORS.white, 0.15), paddingTop: 6 }}
              onPress={toggleVideo}
              activeOpacity={0.8}
              accessibilityLabel={!isVideoEnabled ? "Nyalakan Kamera" : "Matikan Kamera"}
              accessibilityRole="button"
            >
              <MaterialCommunityIcons name={!isVideoEnabled ? 'camera-off' : 'camera'} size={24} color={COLORS.white} />
              <Text style={{ color: COLORS.white, ...TYPOGRAPHY.caption, fontWeight: '500', marginTop: 4 }}>{!isVideoEnabled ? 'Nyalakan' : 'Matikan'}</Text>
            </TouchableOpacity>

            {/* Switch Camera */}
            <TouchableOpacity
              style={{ alignItems: 'center', justifyContent: 'center', width: 64, height: 76, borderRadius: 20, backgroundColor: withOpacity(COLORS.white, 0.15), paddingTop: 6 }}
              onPress={flipCamera}
              activeOpacity={0.8}
              accessibilityLabel="Ganti Kamera"
              accessibilityRole="button"
            >
              <MaterialCommunityIcons name="camera-flip-outline" size={24} color={COLORS.white} />
              <Text style={{ color: COLORS.white, ...TYPOGRAPHY.caption, fontWeight: '500', marginTop: 4 }}>Flip</Text>
            </TouchableOpacity>

            {/* End Call */}
            <TouchableOpacity
              style={{ alignItems: 'center', justifyContent: 'center', width: 64, height: 76, borderRadius: 20, backgroundColor: COLORS.error, paddingTop: 6 }}
              onPress={handleEndCall}
              activeOpacity={0.8}
              accessibilityLabel="Akhiri Panggilan"
              accessibilityRole="button"
            >
              <MaterialCommunityIcons name="phone-hangup" size={24} color={COLORS.white} />
              <Text style={{ color: COLORS.white, ...TYPOGRAPHY.caption, fontWeight: '500', marginTop: 4 }}>Akhiri</Text>
            </TouchableOpacity>
          </View>
        </View>
      </Animated.View>
    );
  };

  // ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
  //  MAIN RENDER
  // ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━

  return (
    <View style={{ flex: 1, backgroundColor: COLORS.background }}>
      <StatusBar barStyle="light-content" backgroundColor={COLORS.primary} />

      {renderHeader()}

      {appointmentId && !socketConnected && sessionStatus !== 'ended' && (
        <View style={{ backgroundColor: COLORS.warning, paddingVertical: 8, paddingHorizontal: 16, flexDirection: 'row', alignItems: 'center', justifyContent: 'center' }}>
          <MaterialCommunityIcons name="wifi-off" size={16} color={COLORS.white} style={{ marginRight: 8 }} />
          <Text style={{ color: COLORS.white, fontSize: 12, fontWeight: '600' }}>
            {reconnectError || (connectionState === 'connecting' ? 'Menghubungkan ulang sesi chat...' : 'Koneksi terputus. Menghubungkan kembali...')}
          </Text>
        </View>
      )}

      <KeyboardAvoidingView
        style={{ flex: 1 }}
        behavior={Platform.OS === 'ios' ? 'padding' : 'height'}
        keyboardVerticalOffset={Platform.OS === 'ios' ? 0 : 20}
      >
        {renderChatView()}
        {renderInputBar()}
      </KeyboardAvoidingView>

      {/* Overlays */}
      {renderPreSessionHealthForm()}
      {renderIncomingCallOverlay()}
      {renderVideoCallOverlay()}
      {showConnectionDiagnostics && (
        <View style={{ ...StyleSheet.absoluteFillObject, zIndex: 130, backgroundColor: withOpacity(COLORS.black, 0.45), justifyContent: 'flex-end' }}>
          <View style={{ backgroundColor: COLORS.white, borderTopLeftRadius: 28, borderTopRightRadius: 28, padding: 20, paddingBottom: Math.max(insets.bottom, 20) }}>
            <View style={{ flexDirection: 'row', alignItems: 'center', marginBottom: 12 }}>
              <MaterialCommunityIcons name="chart-line" size={22} color={COLORS.primary} />
              <Text style={{ ...TYPOGRAPHY.h3, color: COLORS.textPrimary, marginLeft: 10, flex: 1 }}>Diagnostik Koneksi</Text>
              <TouchableOpacity onPress={() => setShowConnectionDiagnostics(false)} accessibilityLabel="Tutup diagnostik koneksi">
                <MaterialCommunityIcons name="close" size={22} color={COLORS.textMuted} />
              </TouchableOpacity>
            </View>
            {qualityHistoryRef.current.slice(-8).map((item) => (
              <View key={item.timestamp} style={{ flexDirection: 'row', alignItems: 'center', paddingVertical: 8, borderBottomWidth: 1, borderBottomColor: COLORS.gray100 }}>
                <Text style={{ ...TYPOGRAPHY.caption, color: COLORS.textMuted, width: 78 }}>
                  {new Date(item.timestamp).toLocaleTimeString('id-ID', { hour: '2-digit', minute: '2-digit', second: '2-digit' })}
                </Text>
                <View style={{ flex: 1, height: 8, borderRadius: 4, backgroundColor: COLORS.gray100, overflow: 'hidden' }}>
                  <View style={{ width: `${Math.max(8, (item.quality / 5) * 100)}%`, height: '100%', backgroundColor: item.quality <= 1 ? COLORS.error : item.quality <= 2 ? COLORS.warning : COLORS.success }} />
                </View>
                <Text style={{ ...TYPOGRAPHY.caption, color: COLORS.textPrimary, marginLeft: 10, fontWeight: '800' }}>{item.quality}/5</Text>
              </View>
            ))}
          </View>
        </View>
      )}

      <PreCallSystemCheckSheet
        visible={preCallSystemCheck.visible}
        checks={preCallSystemCheck.checks}
        canJoin={preCallSystemCheck.canJoin}
        audioOnly={preCallSystemCheck.audioOnly}
        joining={callJoinStatus === 'connecting'}
        labels={{
          title: t('mobile.teledentistry.preCall.title', { fallbackText: 'Pemeriksaan Sebelum Panggilan' }),
          close: t('common.actions.close', { fallbackText: 'Tutup' }),
          ready: t('mobile.teledentistry.preCall.ready', { fallbackText: 'Siap bergabung' }),
          joinAudioOnly: t('mobile.teledentistry.preCall.joinAudioOnly', { fallbackText: 'Bergabung audio saja' }),
          recordingConsent: t('mobile.teledentistry.preCall.recordingConsent', { fallbackText: 'Saya memahami sesi ini mungkin direkam untuk keperluan dokumentasi klinis sesuai kebijakan privasi Serene Apps.' }),
        }}
        onClose={() => setPreCallSystemCheck({ visible: false, session: null, checks: [], canJoin: false, audioOnly: false })}
        onJoin={async () => {
          if (!preCallSystemCheck.session) return;
          try {
            await completeAcceptCall(preCallSystemCheck.session, { enableVideo: !preCallSystemCheck.audioOnly });
            setPreCallSystemCheck({ visible: false, session: null, checks: [], canJoin: false, audioOnly: false });
          } catch (error) {
            const message = error?.message || 'Gagal memulai video call. Silakan coba lagi.';
            setCallNotice(message);
            Alert.alert('Gagal Bergabung', message);
            setCallJoinStatus('idle');
          }
        }}
      />

      {/* Global Twilio Video Engine */}
      <SafeTwilioVideo ref={twilioRef} {...handlers} />
    </View>
  );
};

export default PatientTeledentistryScreen;

import React, { useEffect, useState, useRef, useCallback } from 'react';
import { View, ScrollView, TouchableOpacity, StatusBar, Linking, BackHandler, AppState, StyleSheet, Alert } from 'react-native';
import { Text, Button, ActivityIndicator } from 'react-native-paper';
import { MaterialCommunityIcons } from '@expo/vector-icons';
import { useNavigation, useRoute, useFocusEffect } from '@react-navigation/native';
import { LinearGradient } from 'expo-linear-gradient';
import { useSafeAreaInsets } from 'react-native-safe-area-context';
import { formatCurrency } from '../../../utils/formatters';
import { createSnapTransaction, getPaymentStatus, reconcilePayment } from '../../../services/paymentService';
import ValidationToast from '../../settings/components/ValidationToast';
import useToast from '../../../hooks/useToast';
import { useI18n } from '../../../hooks/useI18n';
import { colors as THEME_COLORS, withOpacity } from '../../../theme/colors';
import { typography as TYPOGRAPHY } from '../../../theme/dimensions';

const COLORS = THEME_COLORS;

const PaymentScreen = () => {
  const navigation = useNavigation();
  const route = useRoute();
  const insets = useSafeAreaInsets();
  const { toast, showToast, hideToast } = useToast();
  const { t } = useI18n();

  // Params from BookingConfirm
  const { appointmentId, dentist, slot, date, fee, paymentMethod, type, treatmentPlanId, invoiceId, source, planTitle } = route.params || {};
  const isVirtual = type === 'virtual';
  const isTreatmentPlanPayment = source === 'treatment_plan' || Boolean(treatmentPlanId || invoiceId);

  // State
  const [loading, setLoading] = useState(true);
  const [checking, setChecking] = useState(false);
  const [paymentIntentId, setPaymentIntentId] = useState(null);
  const [redirectUrl, setRedirectUrl] = useState(null);
  const [status, setStatus] = useState('pending');
  const [polling, setPolling] = useState(false);
  const [expiresAt, setExpiresAt] = useState(null);
  const [remainingSeconds, setRemainingSeconds] = useState(15 * 60);

  const pollInterval = useRef(null);
  const appState = useRef(AppState.currentState);
  const paymentIntentIdRef = useRef(paymentIntentId);
  const mountedRef = useRef(true);

  // Keep ref in sync
  useEffect(() => { paymentIntentIdRef.current = paymentIntentId; }, [paymentIntentId]);
  useEffect(() => () => { mountedRef.current = false; }, []);

  const stopPolling = useCallback(() => {
    if (pollInterval.current) {
      clearInterval(pollInterval.current);
      pollInterval.current = null;
    }
    setPolling(false);
  }, []);

  const initPayment = useCallback(async () => {
    if (!appointmentId && !treatmentPlanId && !invoiceId) return;
    try {
      setLoading(true);
      setStatus('pending');
      const result = await createSnapTransaction({ appointmentId, treatmentPlanId, invoiceId });

      setPaymentIntentId(result.paymentIntentId);
      setRedirectUrl(result.redirectUrl);
      const expiry = result.expiresAt || result.expiryTime || result.metadata?.expiresAt;
      const expiryDate = expiry ? new Date(expiry) : new Date(Date.now() + 15 * 60 * 1000);
      setExpiresAt(expiryDate);
      setRemainingSeconds(Math.max(0, Math.floor((expiryDate.getTime() - Date.now()) / 1000)));

      setLoading(false);

      // Check status immediately (useful if auto-settled in backend)
      try {
        const statusCheck = await getPaymentStatus(result.paymentIntentId);
        const wasFinal = handleStatusChange(statusCheck.status);
        if (wasFinal) {
          return;
        }
      } catch (checkErr) {
        if (__DEV__) console.log('[PaymentScreen] Immediate check error:', checkErr.message);
      }

      setPolling(true);
    } catch (error) {
      const errMsg = error.message || error.error?.message || '';
      const errCode = error.code || error.error?.code || '';
      if (
        errMsg.includes('Payment already completed') ||
        errMsg.includes('Active payment intent already exists') ||
        errCode === 'ACTIVE_PAYMENT_EXISTS'
      ) {
        setStatus('succeeded');
        handleSuccess();
        return;
      }
      if (__DEV__) console.error('[PaymentScreen] Init error:', error);
      setLoading(false);
      setStatus('error');
      showToast(error.message || 'Gagal menyiapkan pembayaran', 'error');
    }
  }, [appointmentId, invoiceId, showToast, treatmentPlanId]);

  // 1. Initialize Transaction
  useEffect(() => {
    initPayment();
  }, [initPayment]);

  useEffect(() => {
    if (!expiresAt || status !== 'pending') return undefined;
    const timer = setInterval(() => {
      const seconds = Math.max(0, Math.floor((expiresAt.getTime() - Date.now()) / 1000));
      setRemainingSeconds(seconds);
      if (seconds <= 0) {
        clearInterval(timer);
        stopPolling();
        setStatus('expired');
        Alert.alert('Waktu pembayaran habis', 'Ingin mencoba lagi?', [
          { text: 'Batal', style: 'cancel', onPress: () => navigation.navigate('AppointmentList') },
          { text: 'Coba Lagi', onPress: initPayment },
        ]);
      }
    }, 1000);
    return () => clearInterval(timer);
  }, [expiresAt, initPayment, navigation, status, stopPolling]);

  // 2. AppState Listener for Foreground Reconcile (uses ref to avoid stale closure)
  useEffect(() => {
    const subscription = AppState.addEventListener('change', nextAppState => {
      if (
        appState.current.match(/inactive|background/) &&
        nextAppState === 'active'
      ) {
        if (__DEV__) console.log('[PaymentScreen] App came to foreground, reconciling...');
        // Use ref to always have latest paymentIntentId
        if (paymentIntentIdRef.current && mountedRef.current) {
          handleSync();
        }
      }
      appState.current = nextAppState;
    });

    return () => {
      subscription.remove();
    };
  }, []);

  // 3. Status Polling (10s interval, only when active)
  useEffect(() => {
    if (polling && paymentIntentId) {
      pollInterval.current = setInterval(async () => {
        // Only poll if we are in foreground
        if (AppState.currentState !== 'active') return;

        try {
          const result = await getPaymentStatus(paymentIntentId);
          if (__DEV__) console.log('[PaymentScreen] Polling status:', result.status);
          handleStatusChange(result.status);
        } catch (error) {
          if (__DEV__) console.log('[PaymentScreen] Poll error:', error.message);
        }
      }, 10000); // Increased to 10s
    }

    return () => stopPolling();
  }, [polling, paymentIntentId]);

  const handleStatusChange = (newStatus) => {
    const successStatuses = ['paid', 'settled', 'succeeded', 'settlement', 'capture'];
    const expiredStatuses = ['expired', 'expire'];
    const failureStatuses = ['failed', 'cancelled', 'deny', 'cancel'];

    if (successStatuses.includes(newStatus)) {
      stopPolling();
      setStatus('succeeded');
      handleSuccess();
      return true;
    } else if (expiredStatuses.includes(newStatus)) {
      stopPolling();
      setStatus('expired');
      return true;
    } else if (failureStatuses.includes(newStatus)) {
      stopPolling();
      setStatus('failed');
      handleFailure(newStatus);
      return true;
    }
    return false;
  };

  const handleSync = async () => {
    if (!paymentIntentId || checking) return;
    try {
      setChecking(true);
      // Try reconciliation first (checks with provider)
      if (__DEV__) console.log('[PaymentScreen] Syncing transaction...');
      const result = await reconcilePayment(paymentIntentId);

      const wasFinal = handleStatusChange(result.newStatus);

      if (!wasFinal) {
        // If still pending after sync, start/resume lower-freq polling
        if (!polling) setPolling(true);
        showToast('Pembayaran belum diterima. Silakan cek lagi nanti.', 'warning');
      }
    } catch (error) {
      if (__DEV__) console.error('[PaymentScreen] Sync error:', error);
      // Fallback to simple status check
      try {
        const result = await getPaymentStatus(paymentIntentId);
        handleStatusChange(result.status);
      } catch (e) { }
    } finally {
      setChecking(false);
    }
  };

  const handleSuccess = () => {
    const safeAppointmentId = route.params?.appointmentId;
    let bookingIdSuffix = 'UNKNOWN';
    if (safeAppointmentId !== undefined && safeAppointmentId !== null) {
      const cleanId = String(safeAppointmentId).replace(/[^a-zA-Z0-9]/g, '');
      if (cleanId && cleanId !== 'undefined' && cleanId !== 'null') {
        bookingIdSuffix = cleanId.slice(-6).toUpperCase();
      }
    }
    if (bookingIdSuffix === 'UNKNOWN') {
      bookingIdSuffix = String(Date.now()).slice(-6);
    }

    if (isTreatmentPlanPayment) {
      navigation.navigate('TreatmentPlan', { refreshedAt: Date.now(), paidTreatmentPlanId: treatmentPlanId });
      return;
    }

    navigation.navigate('BookingSuccess', {
      appointmentId: safeAppointmentId,
      dentist,
      slot,
      date,
      fee,
      type,
      bookingId: `SRN-${bookingIdSuffix}`,
    });
  };

  const handleFailure = (reason) => {
    navigation.navigate('BookingFailed', {
      errorType: 'payment_failed',
      errorCode: reason,
      dentist,
      slot,
      date,
      fee,
      type,
    });
  };

  const handleOpenPayment = () => {
    if (redirectUrl) Linking.openURL(redirectUrl);
  };

  const canRetryPayment = ['expired', 'failed', 'deny', 'cancel', 'error'].includes(status);
  const canOpenPayment = Boolean(redirectUrl) && !loading && !['expired', 'failed', 'deny', 'cancel', 'error'].includes(status);
  const timerLabel = `${Math.floor(remainingSeconds / 60).toString().padStart(2, '0')}:${(remainingSeconds % 60).toString().padStart(2, '0')}`;

  // Prevent accidental back navigation during active payment session
  useFocusEffect(
    React.useCallback(() => {
      const onBackPress = () => {
        if (status === 'pending') {
          Alert.alert(
            'Pembayaran Sedang Berlangsung',
            'Anda yakin ingin kembali? Anda bisa melanjutkan pembayaran nanti melalui menu "Appointments".',
            [
              { text: 'Tetap di Sini', style: 'cancel' },
              {
                text: 'Kembali',
                style: 'destructive',
                onPress: () => {
                  stopPolling();
                  navigation.goBack();
                },
              },
            ]
          );
          return true;
        }
        return false;
      };

      const subscription = BackHandler.addEventListener('hardwareBackPress', onBackPress);
      return () => subscription.remove();
    }, [status, navigation, stopPolling])
  );

  if (loading && !paymentIntentId) {
    return (
      <View style={{ flex: 1, justifyContent: 'center', alignItems: 'center', backgroundColor: COLORS.surface }}>
        <ActivityIndicator size="large" color={COLORS.primary} />
        <Text style={{ ...TYPOGRAPHY.bodyLarge, marginTop: 16 }}>
          {t('mobile.payment.preparing', { fallbackText: 'Menyiapkan gerbang pembayaran...' })}
        </Text>
      </View>
    );
  }

  return (
    <View style={{ flex: 1, backgroundColor: COLORS.surface }}>
      <StatusBar barStyle='light-content' />

      <LinearGradient
        colors={[COLORS.primary, COLORS.primaryLight]}
        style={{ paddingTop: insets.top + 20, paddingBottom: 40, paddingHorizontal: 20, borderBottomLeftRadius: 32, borderBottomRightRadius: 32 }}
      >
        <View style={{ flexDirection: 'row', alignItems: 'center', marginBottom: 24 }}>
          <TouchableOpacity
            onPress={() => {
              if (status === 'pending') {
                Alert.alert(
                  'Pembayaran Sedang Berlangsung',
                  'Anda yakin ingin kembali? Anda bisa melanjutkan pembayaran nanti melalui menu "Appointments".',
                  [
                    { text: 'Tetap di Sini', style: 'cancel' },
                    {
                      text: 'Kembali',
                      style: 'destructive',
                      onPress: () => {
                        stopPolling();
                        navigation.goBack();
                      },
                    },
                  ]
                );
              } else {
                navigation.goBack();
              }
            }}
            accessibilityLabel="Kembali"
            accessibilityRole="button"
            style={{ width: 40, height: 40, borderRadius: 20, backgroundColor: withOpacity(COLORS.white, 0.2), justifyContent: 'center', alignItems: 'center' }}
          >
            <MaterialCommunityIcons name="arrow-left" size={24} color={COLORS.surfaceElevated} />
          </TouchableOpacity>
          <Text style={{ ...TYPOGRAPHY.h3, color: COLORS.surfaceElevated, marginLeft: 16 }}>
            {t('mobile.payment.title', { fallbackText: 'Pembayaran' })}
          </Text>
        </View>

        <View style={{ alignItems: 'center' }}>
          <Text style={{ ...TYPOGRAPHY.caption, color: withOpacity(COLORS.white, 0.8), textTransform: 'uppercase', letterSpacing: 1 }}>{isTreatmentPlanPayment ? 'TOTAL RENCANA PERAWATAN' : 'TOTAL PEMBAYARAN'}</Text>
          <Text style={{ ...TYPOGRAPHY.h1, color: COLORS.surfaceElevated, fontSize: 32, marginTop: 4 }}>{formatCurrency(fee)}</Text>
          <View style={{ marginTop: 12, borderRadius: 999, backgroundColor: remainingSeconds <= 5 * 60 ? COLORS.error : COLORS.warning, paddingHorizontal: 14, paddingVertical: 7, flexDirection: 'row', alignItems: 'center' }}>
            <MaterialCommunityIcons name="timer-sand" size={16} color={COLORS.white} />
            <Text style={{ marginLeft: 6, color: COLORS.white, fontWeight: '900' }}>{timerLabel}</Text>
          </View>
        </View>
      </LinearGradient>

      <ScrollView contentContainerStyle={{ padding: 20, paddingBottom: 100 }}>
        {/* Status Card */}
        <View style={{ backgroundColor: COLORS.surfaceElevated, borderRadius: 24, padding: 20, marginBottom: 24, shadowColor: COLORS.textPrimary, shadowOpacity: 0.05, shadowRadius: 10, elevation: 2 }}>
          <View style={{ flexDirection: 'row', alignItems: 'center', marginBottom: 16 }}>
            <View style={{ width: 48, height: 48, borderRadius: 24, backgroundColor: withOpacity(COLORS.primary, 0.1), justifyContent: 'center', alignItems: 'center' }}>
              <MaterialCommunityIcons name="clock-outline" size={24} color={COLORS.primary} />
            </View>
            <View style={{ marginLeft: 16 }}>
              <Text style={{ ...TYPOGRAPHY.bodyLarge, fontWeight: '700', color: COLORS.textPrimary }}>
                {status === 'expired'
                  ? t('mobile.payment.expiredTitle', { fallbackText: 'Pembayaran Kedaluwarsa' })
                  : t('mobile.payment.pendingTitle', { fallbackText: 'Menunggu Pembayaran' })}
              </Text>
              <Text style={{ ...TYPOGRAPHY.bodySmall, color: COLORS.textSecondary }}>Selesaikan pembayaran sebelum waktu habis</Text>
            </View>
          </View>

          <Text style={{ ...TYPOGRAPHY.bodySmall, color: COLORS.textSecondary, lineHeight: 20 }}>
            Silakan selesaikan pembayaran Anda melalui gerbang pembayaran aman Midtrans menggunakan metode {paymentMethod === 'card' ? 'Kartu Kredit/Debit' : paymentMethod === 'va' ? 'Virtual Account' : 'yang dipilih'}.
          </Text>

          <Button
            mode="contained"
            onPress={handleOpenPayment}
            disabled={!canOpenPayment}
            style={{ marginTop: 20, borderRadius: 12 }}
            buttonColor={COLORS.primary}
            contentStyle={{ height: 48 }}
            accessibilityLabel="Buka Pembayaran Midtrans"
          >
            {t('mobile.payment.openPayment', { fallbackText: 'Buka Pembayaran Midtrans' })}
          </Button>
          {canRetryPayment && (
            <Button
              mode="text"
              onPress={initPayment}
              style={{ marginTop: 8 }}
              textColor={COLORS.primary}
            >
              {t('mobile.payment.retryPayment', { fallbackText: 'Coba buat transaksi baru' })}
            </Button>
          )}
        </View>

        <View style={{ marginBottom: 16 }}>
          <Text style={{ ...TYPOGRAPHY.bodyLarge, fontWeight: '700', color: COLORS.textPrimary }}>Ringkasan Pesanan</Text>
        </View>

        <LinearGradient
          colors={[withOpacity(COLORS.primary, 0.05), COLORS.surfaceElevated]}
          style={{ borderRadius: 24, padding: 18, marginBottom: 22, shadowColor: COLORS.primary, shadowOffset: { width: 0, height: 8 }, shadowOpacity: 0.08, shadowRadius: 18, elevation: 4 }}
        >
          <View style={{ flexDirection: 'row', justifyContent: 'space-between', marginBottom: 12 }}>
            <View>
              <Text style={{ ...TYPOGRAPHY.h5, color: COLORS.textPrimary }}>
                {isTreatmentPlanPayment
                  ? (planTitle || 'Rencana Perawatan')
                  : new Date(date).toLocaleDateString('id-ID', { weekday: 'long', day: 'numeric', month: 'long' })}
              </Text>
              <Text style={{ ...TYPOGRAPHY.caption, color: COLORS.textSecondary, marginTop: 2 }}>{slot?.time || '—'} WIB</Text>
            </View>
            <View style={{ alignItems: 'flex-end' }}>
              <View style={{ flexDirection: 'row', alignItems: 'center' }}>
                <MaterialCommunityIcons name={isVirtual ? 'video' : 'map-marker'} size={16} color={COLORS.primary} />
                <Text style={{ ...TYPOGRAPHY.caption, color: COLORS.textMuted, marginLeft: 4 }}>{isVirtual ? 'Konsultasi Video Online' : 'Tatap muka'}</Text>
                {isVirtual && <View style={{ width: 7, height: 7, borderRadius: 4, backgroundColor: COLORS.success, marginLeft: 6 }} />}
              </View>
            </View>
          </View>
          <View style={{ flexDirection: 'row', alignItems: 'center' }}>
            <View style={{ width: 52, height: 52, borderRadius: 20, backgroundColor: withOpacity(COLORS.primary, 0.1), alignItems: 'center', justifyContent: 'center', marginRight: 12 }}>
              <MaterialCommunityIcons name='account-heart' size={26} color={COLORS.primary} />
            </View>
            <View>
              <Text style={{ ...TYPOGRAPHY.h5, color: COLORS.textPrimary }}>{isVirtual ? 'Menunggu Pembayaran' : dentist?.name}</Text>
              <Text style={{ ...TYPOGRAPHY.bodySmall, color: COLORS.textSecondary, marginTop: 2 }}>{isVirtual ? 'Dokter akan ditugaskan otomatis' : dentist?.specialty}</Text>
            </View>
          </View>
        </LinearGradient>

        {/* Action Controls */}
        <View style={{ marginTop: 32, alignItems: 'center' }}>
          <Button
            mode="outlined"
            onPress={handleSync}
            loading={checking}
            disabled={checking}
            style={{ borderRadius: 12, borderColor: COLORS.primary, borderWidth: 1.5, width: '100%' }}
            labelStyle={{ fontWeight: '700', color: COLORS.primary }}
            accessibilityLabel="Cek Status Pembayaran Manual"
          >
            CEK STATUS PEMBAYARAN
          </Button>

          <View style={{ flexDirection: 'row', alignItems: 'center', marginTop: 12 }}>
            <ActivityIndicator animating={polling && !checking} size={12} color={COLORS.textMuted} style={{ marginRight: 8 }} />
            <Text style={{ ...TYPOGRAPHY.caption, color: COLORS.textMuted }}>
              {polling ? 'Pengecekan otomatis berjalan (10s)...' : 'Gunakan tombol di atas jika sudah bayar'}
            </Text>
          </View>
        </View>
      </ScrollView>

      {(loading || checking) && (
        <View style={{ ...StyleSheet.absoluteFillObject, backgroundColor: withOpacity(COLORS.white, 0.7), justifyContent: 'center', alignItems: 'center', zIndex: 100 }}>
          <ActivityIndicator size="large" color={COLORS.primary} />
          {checking && <Text style={{ ...TYPOGRAPHY.bodySmall, marginTop: 12, color: COLORS.primary, fontWeight: '600' }}>Menyinkronkan status...</Text>}
        </View>
      )}

      <ValidationToast
        visible={toast.visible}
        message={toast.message}
        status={toast.status}
        onDismiss={hideToast}
      />
    </View>
  );
};

