import React, { useMemo, useState } from 'react';
import { View, ScrollView, TouchableOpacity, Image, Linking, Dimensions } from 'react-native';
import { Text, useTheme } from 'react-native-paper';
import { MaterialCommunityIcons } from '@expo/vector-icons';
import { LinearGradient } from 'expo-linear-gradient';
import { SAMPLE_ARTICLES } from '../data/articles';

const { width } = Dimensions.get('window');
const SIDE = 12;
const GAP = 12;
const CARD_W = width - SIDE * 2 - 40; // smaller width with more margin
const SNAP_INTERVAL = CARD_W + GAP;

export const formatArticleRelativeTime = (iso) => {
  if (!iso) return '';
  const t = new Date(iso).getTime();
  if (Number.isNaN(t)) return '';
  const diffSeconds = Math.max(1, Math.floor((Date.now() - t) / 1000));
  if (diffSeconds < 60) return `${diffSeconds} detik lalu`;
  const diffMinutes = Math.floor(diffSeconds / 60);
  if (diffMinutes < 60) return `${diffMinutes} menit lalu`;
  const diffHours = Math.floor(diffMinutes / 60);
  if (diffHours < 24) return `${diffHours} jam lalu`;
  const diffDays = Math.floor(diffHours / 24);
  if (diffDays < 7) return `${diffDays} hari lalu`;
  const diffWeeks = Math.floor(diffDays / 7);
  if (diffWeeks < 4) return `${diffWeeks} minggu lalu`;
  const diffMonths = Math.floor(diffWeeks / 4);
  if (diffMonths < 12) return `${diffMonths} bulan lalu`;
  const diffYears = Math.floor(diffMonths / 12);
  return `${diffYears} tahun lalu`;
};

export default function Article({ title='Artikel kesehatan gigi', subtitle='Kumpulan sumber tepercaya untuk Anda', articles=[], onOpen, onSeeAll }) {
  const theme = useTheme();
  const data = useMemo(() => (articles.length ? articles : SAMPLE_ARTICLES), [articles]);
  const [activeIndex, setActiveIndex] = useState(0);
  const open = (url, item)=>{ if(url){ try{ Linking.openURL(url); } catch(e){} } onOpen?.(url, item); };
  const handleMomentumEnd = (e)=>{ const offset = e.nativeEvent.contentOffset.x; const idx = Math.round(offset / SNAP_INTERVAL); setActiveIndex(Math.max(0, Math.min(idx, data.length-1))); };

  return (
    <View style={{ paddingHorizontal:SIDE, marginBottom:24 }}>
      <View style={{ flexDirection:'row', justifyContent:'space-between', alignItems:'center', marginBottom:16 }}>
        <View><Text style={{ fontSize:22, fontWeight:'bold', color:'#1F2937', marginBottom:4 }}>{title}</Text><Text style={{ fontSize:14, color:'#6B7280', fontWeight:'500' }}>{subtitle}</Text></View>
        <TouchableOpacity
          onPress={() => onSeeAll?.(data)}
          style={{ backgroundColor:'#F3F4F6', borderRadius:12, padding:8 }}
        >
          <MaterialCommunityIcons name="dots-horizontal" size={24} color={theme.colors.primary} />
        </TouchableOpacity>
      </View>

      <ScrollView
        horizontal
        showsHorizontalScrollIndicator={false}
        contentContainerStyle={{ paddingRight:SIDE }}
        snapToInterval={SNAP_INTERVAL}
        snapToAlignment="start"
        decelerationRate="fast"
        disableIntervalMomentum
        onMomentumScrollEnd={handleMomentumEnd}
      >
        {data.map((a, idx)=>(
          <TouchableOpacity key={a.id || idx} activeOpacity={0.9} onPress={()=>open(a.url, a)} style={{ width:CARD_W, marginRight:GAP }}>
            <View style={{ borderRadius:20, overflow:'hidden', backgroundColor:'#EEE' }}>
              <Image source={{ uri:a.image }} style={{ width:'100%', height:180 }} resizeMode="cover" />
              <LinearGradient colors={['rgba(0,0,0,0)','rgba(0,0,0,0.65)']} start={{x:0,y:0}} end={{x:0,y:1}} style={{ position:'absolute', left:0, right:0, bottom:0, height:120 }} />
              {a.category ? <View style={{ position:'absolute', top:12, left:12, backgroundColor:'rgba(255,255,255,0.9)', paddingHorizontal:10, paddingVertical:6, borderRadius:14 }}><Text style={{ fontSize:12, fontWeight:'600', color:theme.colors.primary }}>{a.category}</Text></View> : null}
              <View style={{ position:'absolute', top:12, right:12, backgroundColor:'rgba(255,255,255,0.9)', width:36, height:36, borderRadius:18, alignItems:'center', justifyContent:'center' }}><MaterialCommunityIcons name="open-in-new" size={18} color={theme.colors.primary} /></View>
              <View style={{ position:'absolute', left:16, right:16, bottom:14 }}>
                <Text numberOfLines={2} style={{ fontSize:16, fontWeight:'700', color:'#FFF', marginBottom:6 }}>{a.title}</Text>
                <View style={{ flexDirection:'row', alignItems:'center', opacity:0.9 }}>
                  <MaterialCommunityIcons name="newspaper-variant-outline" size={14} color="#FFF" />
                  <Text style={{ marginLeft:6, fontSize:12, color:'#FFF' }}>{a.source || 'Sumber'}</Text>
                  <View style={{ width:4, height:4, borderRadius:2, backgroundColor:'rgba(255,255,255,0.8)', marginHorizontal:8 }} />
                  <MaterialCommunityIcons name="clock-time-four-outline" size={14} color="#FFF" />
                  <Text style={{ marginLeft:6, fontSize:12, color:'#FFF' }}>{formatArticleRelativeTime(a.publishedAt)}</Text>
                </View>
              </View>
            </View>
          </TouchableOpacity>
        ))}
      </ScrollView>
      <View style={{ flexDirection:'row', justifyContent:'center', marginTop:12 }}>
        {data.map((a, idx)=>(
          <View key={`${a.id || idx}-dot`} style={{ width:idx===activeIndex?18:8, height:8, borderRadius:4, marginHorizontal:4, backgroundColor:idx===activeIndex?theme.colors.primary:'#E5E7EB' }} />
        ))}
      </View>
    </View>
  );
}

import React, { useRef, useState, useEffect, useMemo } from 'react';
import { View, TouchableOpacity, Image, Dimensions, Animated } from 'react-native';
import { Text, useTheme } from 'react-native-paper';
import { MaterialCommunityIcons } from '@expo/vector-icons';
import { LinearGradient } from 'expo-linear-gradient';
import resolveMediaUrl from '../../../utils/media';

const { width } = Dimensions.get('window');
// layout constants — bikin kartu center & scroll enak
const SIDE_INSET = 20;              // padding kiri/kanan container
const GAP = 16;                     // jarak antar kartu
const CARD_W = width - SIDE_INSET * 2;
const PAGE_W = CARD_W + GAP;        // << ini dipakai utk snapToInterval & perhitungan index

const currencyFormatter = new Intl.NumberFormat('id-ID', {
  style: 'currency',
  currency: 'IDR',
  maximumFractionDigits: 0,
});

function getAppointmentStatus(a) {
  if (!a?.startsAt) return { text: 'Terjadwal', canJoin: false, minutesUntil: null };
  const now = new Date();
  const t = new Date(a.startsAt);
  const diffM = Math.floor((t - now) / 60000);

  if (diffM < 0) return { text: 'Selesai', canJoin: false, minutesUntil: diffM };
  if (diffM <= 30) return { text: `Mulai dalam ${diffM} menit`, canJoin: true, minutesUntil: diffM };
  if (diffM <= 60) return { text: 'Mulai dalam 1 jam', canJoin: false, minutesUntil: diffM };
  const h = Math.floor(diffM / 60);
  if (h < 24) return { text: `Mulai dalam ${h} jam`, canJoin: false, minutesUntil: diffM };
  const d = Math.floor(h / 24);
  return { text: d === 1 ? 'Besok' : `Dalam ${d} hari`, canJoin: false, minutesUntil: diffM };
}

function formatAppointmentTime(s) {
  if (!s) return 'Belum ditentukan';
  const d = new Date(s);
  const h = d.getHours().toString().padStart(2, '0');
  const m = d.getMinutes().toString().padStart(2, '0');
  return `${h}:${m}`;
}

const FeaturedDoctors = ({ appointments = [], onDoctorPress, onJoinCall }) => {
  const theme = useTheme();
  const scrollRef = useRef(null);
  const scrollX = useRef(new Animated.Value(0)).current;
  const [currentIndex, setCurrentIndex] = useState(0);

  // Map appointments to card data format using useMemo
  const featuredDoctors = useMemo(() => {
    if (!appointments || appointments.length === 0) return [];

    return appointments.map(a => {
      const statusInfo = getAppointmentStatus(a);
      const isVirtual = a.appointmentType === 'virtual' || a.metadata?.appointmentType === 'virtual' || a.type === 'virtual';
      return {
        id: a.id,
        bookingCode: a.bookingCode || `SRN-${String(a.id).padStart(6, '0')}`,
        name: a.dentist?.title
          ? `${a.dentist.title} ${a.dentist.name}`
          : (a.dentist?.name || 'Dokter Gigi'),
        specialty: a.dentist?.specialty || 'Dokter Gigi Umum',
        dentistType: a.dentist?.dentistType || 'clinic',
        experience: a.dentist?.experience || '',
        rating: a.dentist?.rating || 4.8,
        reviews: a.dentist?.reviews || 0,
        price: a.payment?.amount || 0,
        paymentStatus: a.payment?.status || null,
        statusText: statusInfo.text,
        canJoin: statusInfo.canJoin && isVirtual,
        nextSlot: formatAppointmentTime(a.startsAt),
        image: resolveMediaUrl(a.dentist?.avatar) || 'https://images.unsplash.com/photo-1612349317150-e413f6a5b16d?w=400&h=400&fit=crop',
        verified: true,
        appointmentId: a.id,
        startsAt: a.startsAt,
        clinicName: isVirtual ? 'Virtual Consultation' : (a.clinic?.name || (a.dentist?.dentistType === 'independent' ? 'Praktik Mandiri' : '')),
        reason: a.reason || 'Konsultasi gigi',
        type: isVirtual ? 'virtual' : (a.metadata?.appointmentType || a.type || 'onsite'),
        // Pass full appointment for navigation
        fullAppointment: a,
      };
    });
  }, [appointments]);

  // siapkan infinite scroll: start dari batch tengah agar bisa swipe kiri/kanan langsung
  useEffect(() => {
    if (featuredDoctors.length > 0) {
      const x = featuredDoctors.length * PAGE_W;
      setTimeout(() => {
        scrollRef.current?.scrollTo({ x, animated: false });
      }, 0);
    }
  }, [featuredDoctors.length]);

  const handleScroll = useMemo(() => Animated.event(
    [{ nativeEvent: { contentOffset: { x: scrollX } } }],
    {
      useNativeDriver: false,
      listener: (e) => {
        if (featuredDoctors.length === 0) return;
        const page = Math.round(e.nativeEvent.contentOffset.x / PAGE_W);
        const idx = page % featuredDoctors.length;
        setCurrentIndex(((idx % featuredDoctors.length) + featuredDoctors.length) % featuredDoctors.length);
      }
    }
  ), [scrollX, featuredDoctors.length]);

  const onEnd = (e) => {
    if (featuredDoctors.length === 0) return;
    const page = Math.round(e.nativeEvent.contentOffset.x / PAGE_W);
    if (page >= featuredDoctors.length * 2 || page < featuredDoctors.length) {
      const target = (featuredDoctors.length + (page % featuredDoctors.length)) * PAGE_W;
      requestAnimationFrame(() => {
        scrollRef.current?.scrollTo({ x: target, animated: false });
      });
    }
  };

  const _onJoin = (d) => onJoinCall?.(d);
  const _onPress = (d) => onDoctorPress?.(d);

  // Return null AFTER all hooks are called (React rules of hooks)
  if (featuredDoctors.length === 0) {
    return null;
  }

  const data = [...featuredDoctors, ...featuredDoctors, ...featuredDoctors];

  return (
    <View style={{ marginVertical: 16 }}>
      <Animated.ScrollView
        ref={scrollRef}
        horizontal
        showsHorizontalScrollIndicator={false}
        decelerationRate="fast"
        snapToInterval={PAGE_W}
        snapToAlignment="start"
        contentContainerStyle={{ paddingHorizontal: SIDE_INSET }}
        onScroll={handleScroll}
