                        <View style={{ flexDirection: 'row', alignItems: 'center' }}>
                          <MaterialCommunityIcons
                            name={doctor.type === 'virtual' ? 'video-outline' : 'hospital-building'}
                            size={12}
                            color="rgba(255,255,255,0.75)"
