      </Animated.ScrollView>

      {/* Pagination dots */}
      <View style={{ flexDirection: 'row', justifyContent: 'center', marginTop: 12 }}>
        {featuredDoctors.map((_, i) => (
          <View
            key={i}
            style={{
              width: i === currentIndex ? 20 : 8,
              height: 8,
              borderRadius: 4,
              backgroundColor: i === currentIndex ? '#62109F' : '#E5E7EB',
              marginHorizontal: 3
            }}
