                      <MaterialCommunityIcons
                        name="check"
                        size={16}
                        color={theme.colors.primary}
                      />
                    </View>
                    <View style={{ flex: 1 }}>
                      <Text style={{ color: '#0F172A', fontWeight: '600' }}>{facilityName}</Text>
                      {facilityDesc ? (
                        <Text style={{ color: '#94A3B8', fontSize: 12, marginTop: 2 }}>{facilityDesc}</Text>
                      ) : null}
                    </View>
                  </View>
                );
              })}
            </View>
          </Section>

          <Section
            title="Galeri suasana"
            onLayout={(e) => handleSectionLayout('galeri', e)}
          >
            <ScrollView horizontal showsHorizontalScrollIndicator={false}>
              {(clinic.gallery || []).map((item, idx) => {
                // Handle gallery items with structure { image_url, image_type, caption }
                const imageUrl = item?.image_url;

                if (!imageUrl) return null;

                return (
                  <Image
                    key={`gallery-${item?.id || idx}`}
                    source={{ uri: imageUrl }}
                    style={{ width: 220, height: 140, borderRadius: 20, marginRight: 14 }}
                  />
                );
              })}
            </ScrollView>
          </Section>
        </View>
      </ScrollView>

      {/* BOTTOM ACTION BAR */}
      <View
        style={{
          position: 'absolute',
          left: 0,
          right: 0,
          bottom: 0,
          padding: 20,
          backgroundColor: 'white',
          borderTopLeftRadius: 24,
          borderTopRightRadius: 24,
          shadowColor: '#0F172A',
          shadowOffset: { width: 0, height: -4 },
          shadowOpacity: 0.08,
          shadowRadius: 12,
          elevation: 12,
        }}
      >
        <View style={{ flexDirection: 'row' }}>
          <Button
            mode="outlined"
            style={{ flex: 1, marginRight: 12 }}
            onPress={handleCall}
            icon="phone"
          >
            Hubungi
          </Button>
          <Button
            mode="contained"
            style={{ flex: 1 }}
            onPress={handleBook}
            icon="calendar"
          >
            Buat janji
          </Button>
        </View>
      </View>

      <ValidationToast
        visible={toast.visible}
        message={toast.message}
        status={toast.status}
        onDismiss={hideToast}
      />
    </View>
  );
};

