    </View>
  );

  return (
    <View style={{ flex: 1, backgroundColor: '#F8FAFC' }}>
      {/* 3. Update StatusBar agar transparan dan konten naik ke notch */}
      <StatusBar barStyle='light-content' backgroundColor="transparent" translucent />

