    borderRadius: 16,
    flexDirection: 'row',
    alignItems: 'center',
    paddingVertical: 8,
    paddingHorizontal: 12,
  },
  iconWrapper: {
    width: 32,
    height: 32,
    borderRadius: 16,
    backgroundColor: 'rgba(255,255,255,0.20)',
    alignItems: 'center',
    justifyContent: 'center',
    marginRight: 10,
  },
  textGroup: {
    flex: 1,
  },
  label: {
    textTransform: 'uppercase',
    letterSpacing: 1,
    marginBottom: 1,
    opacity: 0.85,
  },
  message: {
    color: '#FFFFFF',
  },
  closeButton: {
