    <View>
      <Text style={{ fontSize: 18, fontWeight: '700', color: '#0F172A' }}>{title}</Text>
      {subtitle ? <Text style={{ color: '#94A3B8', marginTop: 2 }}>{subtitle}</Text> : null}
