  } catch (error) {
    const status = error.response?.status;
    let errorMessage = error.response?.data?.detail || error.message;

    if (__DEV__) {
      console.log('❌ sendChatWithImages error payload:', {
        status,
        data: error.response?.data,
        message: error.message,
      });
