import { createSlice } from '@reduxjs/toolkit';

const AUTH_LEVELS = {
  GUEST: 'guest',
  OTP_VERIFIED: 'otp_verified',
  FULL_ACCOUNT: 'full_account',
};

const initialState = {
  authLevel: AUTH_LEVELS.GUEST,
  user: null,
  patientProfile: null,
  accessToken: null,
  refreshToken: null,
  phoneNumber: null, // For OTP verification
  isLoading: false,
  error: null,
};

const authSlice = createSlice({
  name: 'auth',
  initialState,
  reducers: {
    setAuthLevel: (state, action) => {
      state.authLevel = action.payload;
    },
    setPhoneNumber: (state, action) => {
      state.phoneNumber = action.payload;
    },
    otpVerified: (state, action) => {
      state.authLevel = AUTH_LEVELS.OTP_VERIFIED;
      state.phoneNumber = action.payload.phoneNumber;
    },
    loginSuccess: (state, action) => {
      state.authLevel = AUTH_LEVELS.FULL_ACCOUNT;
      state.user = action.payload.user;
      state.patientProfile = action.payload.patientProfile;
      state.accessToken = action.payload.accessToken;
      state.refreshToken = action.payload.refreshToken;
      state.phoneNumber = action.payload.user?.phone_number || state.phoneNumber;
      state.error = null;
    },
    updateProfile: (state, action) => {
      state.patientProfile = {
        ...state.patientProfile,
        ...action.payload,
      };
    },
    updateUser: (state, action) => {
      state.user = {
        ...state.user,
        ...action.payload,
      };
    },
    logout: (state) => {
      return {
        ...initialState,
        authLevel: AUTH_LEVELS.GUEST,
      };
    },
    setLoading: (state, action) => {
      state.isLoading = action.payload;
    },
    setError: (state, action) => {
      state.error = action.payload;
      state.isLoading = false;
    },
    clearError: (state) => {
      state.error = null;
    },
  },
});

export const {
  setAuthLevel,
  setPhoneNumber,
  otpVerified,
  loginSuccess,
  updateProfile,
  updateUser,
  logout,
  setLoading,
  setError,
  clearError,
} = authSlice.actions;

export { AUTH_LEVELS };
export default authSlice.reducer;

import * as ImageManipulator from 'expo-image-manipulator';
import { Image } from 'react-native';
// Use legacy API to avoid deprecated getInfoAsync warning until new File/Directory API is adopted
import * as FileSystem from 'expo-file-system/legacy';

/**
 * Compress image to reduce file size and speed up upload
 * @param {string} uri - Image URI
 * @param {object} options - Compression options
 * @returns {Promise<{uri: string, width: number, height: number, size: number}>}
 */
export const compressImage = async (uri, options = {}) => {
  const {
    maxWidth = 1920,
    maxHeight = 1920,
    quality = 0.8,
    format = ImageManipulator.SaveFormat.JPEG,
  } = options;

  try {
    // Get original image info
    const fileInfo = await FileSystem.getInfoAsync(uri);
    const originalSize = fileInfo.size || 0;

    // Get original dimensions to avoid upscaling small images
    const getDimensions = () => new Promise(resolve => {
      Image.getSize(
        uri,
        (width, height) => resolve({ width, height }),
        () => resolve({ width: null, height: null })
      );
    });

    const { width: originalWidth, height: originalHeight } = await getDimensions();
    const hasDimensions = Boolean(originalWidth && originalHeight);
    const widthRatio = hasDimensions ? maxWidth / originalWidth : 1;
    const heightRatio = hasDimensions ? maxHeight / originalHeight : 1;
    const scaleRatio = hasDimensions ? Math.min(widthRatio, heightRatio, 1) : 1; // Never upscale
    const shouldResize = hasDimensions && scaleRatio < 1;

    const resizeAction = shouldResize
      ? [{
          resize: {
            width: Math.round(originalWidth * scaleRatio),
            height: Math.round(originalHeight * scaleRatio),
          },
        }]
      : [];

    if (__DEV__) {
      console.log(`📸 Original image: ${(originalSize / 1024).toFixed(2)} KB`);
      if (hasDimensions) {
        console.log(`📏 Original dimensions: ${originalWidth}x${originalHeight}`);
      }
    }

    // Compress and resize
    const manipResult = await ImageManipulator.manipulateAsync(
      uri,
      resizeAction,
      { compress: quality, format }
    );

    // Get compressed image info
    const compressedInfo = await FileSystem.getInfoAsync(manipResult.uri);
    const compressedSize = compressedInfo.size || 0;

    if (__DEV__) {
      if (originalSize > 0) {
        const reduction = ((originalSize - compressedSize) / originalSize * 100).toFixed(1);
        const trend = reduction >= 0 ? 'smaller' : 'larger';
        console.log(
          `✅ Compressed image: ${(compressedSize / 1024).toFixed(2)} KB (${reduction}% ${trend})`
        );
      } else {
        console.log(`✅ Compressed image: ${(compressedSize / 1024).toFixed(2)} KB`);
      }
    }

    return {
      uri: manipResult.uri,
      width: manipResult.width,
      height: manipResult.height,
      size: compressedSize,
      originalSize,
    };
  } catch (error) {
    console.error('❌ Image compression failed:', error);
    // Return original if compression fails
    return { uri, size: 0, originalSize: 0 };
  }
};

/**
 * Compress multiple images
 * @param {string[]} uris - Array of image URIs
 * @param {object} options - Compression options
 * @returns {Promise<Array>}
 */
export const compressImages = async (uris, options = {}) => {
  const results = await Promise.all(
    uris.map(uri => compressImage(uri, options))
  );

  if (__DEV__) {
    const totalOriginal = results.reduce((sum, r) => sum + r.originalSize, 0);
    const totalCompressed = results.reduce((sum, r) => sum + r.size, 0);
    if (totalOriginal > 0) {
      const totalReduction = ((totalOriginal - totalCompressed) / totalOriginal * 100).toFixed(1);
      const trend = totalReduction >= 0 ? 'smaller' : 'larger';
      console.log(
        `📦 Total compression: ${(totalOriginal / 1024).toFixed(2)} KB → ${(totalCompressed / 1024).toFixed(2)} KB (${totalReduction}% ${trend})`
      );
    } else {
      console.log(
        `📦 Total compression: ${(totalCompressed / 1024).toFixed(2)} KB (original size unavailable)`
      );
    }
  }

  return results;
};

/**
 * Check if image needs compression
 * @param {string} uri - Image URI
 * @param {number} maxSize - Max size in bytes (default 500KB)
 * @returns {Promise<boolean>}
 */
export const needsCompression = async (uri, maxSize = 500 * 1024) => {
  try {
    const fileInfo = await FileSystem.getInfoAsync(uri);
    return (fileInfo.size || 0) > maxSize;
  } catch (error) {
    return false;
  }
};

import axios from 'axios';
import { Platform } from 'react-native';
import { API_BASE_URL } from '../services/api';

/**
 * Test backend connection
 * This utility helps verify that mobile app can connect to backend server
 */

export const testBackendConnection = async () => {
  console.log('\n🔍 Testing Backend Connection...');
  console.log('📍 API Base URL:', API_BASE_URL);
  console.log('📱 Platform:', Platform.OS);

  const tests = [];

  // Test 1: Health Check
  try {
    console.log('\n1️⃣ Testing /health endpoint...');
    const response = await axios.get(`${API_BASE_URL}/health`, { timeout: 5000 });
    console.log('✅ Health check passed:', response.data);
    tests.push({ name: 'Health Check', status: 'PASS', data: response.data });
  } catch (error) {
    console.error('❌ Health check failed:', error.message);
    tests.push({ 
      name: 'Health Check', 
      status: 'FAIL', 
      error: error.message,
      hint: 'Make sure backend server is running on port 4000'
    });
  }

  // Test 2: API Version
  try {
    console.log('\n2️⃣ Testing /v1 endpoint...');
    const response = await axios.get(`${API_BASE_URL}/v1`, { timeout: 5000 });
    console.log('✅ API version check passed:', response.data);
    tests.push({ name: 'API Version', status: 'PASS', data: response.data });
  } catch (error) {
    console.error('❌ API version check failed:', error.message);
    tests.push({ 
      name: 'API Version', 
      status: 'FAIL', 
      error: error.message 
    });
  }

  // Test 3: Test Registration Endpoint (without sending data)
  try {
    console.log('\n3️⃣ Testing registration endpoint availability...');
    // Send empty request to check if endpoint exists
    const response = await axios.post(
      `${API_BASE_URL}/v1/auth/patient/register`,
      {},
      { 
        timeout: 5000,
        validateStatus: (status) => status === 400 || status === 201 // Accept both
      }
    );
    console.log('✅ Registration endpoint is available');
    tests.push({ 
      name: 'Registration Endpoint', 
      status: 'PASS',
      note: 'Endpoint exists and responds'
    });
  } catch (error) {
    if (error.response?.status === 400) {
      console.log('✅ Registration endpoint is available (validation working)');
      tests.push({ 
        name: 'Registration Endpoint', 
        status: 'PASS',
        note: 'Endpoint exists, validation is working'
      });
    } else {
      console.error('❌ Registration endpoint test failed:', error.message);
      tests.push({ 
        name: 'Registration Endpoint', 
        status: 'FAIL', 
        error: error.message 
      });
    }
  }

  // Print Summary
  console.log('\n' + '='.repeat(50));
  console.log('📊 CONNECTION TEST SUMMARY');
  console.log('='.repeat(50));

  tests.forEach((test, index) => {
    const icon = test.status === 'PASS' ? '✅' : '❌';
    console.log(`${icon} ${index + 1}. ${test.name}: ${test.status}`);
    if (test.error) {
      console.log(`   Error: ${test.error}`);
    }
    if (test.hint) {
      console.log(`   💡 Hint: ${test.hint}`);
    }
  });

  const allPassed = tests.every(t => t.status === 'PASS');

  console.log('\n' + '='.repeat(50));
  if (allPassed) {
    console.log('🎉 ALL TESTS PASSED! Backend is ready.');
  } else {
    console.log('⚠️  SOME TESTS FAILED. Check errors above.');
  }
  console.log('='.repeat(50) + '\n');

  return {
    allPassed,
    tests,
    apiBaseUrl: API_BASE_URL,
  };
};

// Quick test function for manual testing
export const quickTest = () => {
  console.log('🚀 Running quick backend connection test...');
  testBackendConnection();
};
